fn count_words(text: Str) -> Map<Str, Int> {
  let mut m: Map<Str, Int> = Map::new();
  let mut cur = "";
  for c in text.chars() {
    let letter = (c >= "a" && c <= "z") || (c >= "A" && c <= "Z");
    if letter {
      cur = cur + c.to_lowercase();
    } else {
      if cur.len() > 0 {
        m.insert(cur, m.get(cur).unwrap_or(0) + 1);
      }
      cur = "";
    }
  }
  if cur.len() > 0 {
    m.insert(cur, m.get(cur).unwrap_or(0) + 1);
  }
  m
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?.to_str();
  let m = count_words(text);
  let mut keys = m.keys();
  keys.sort_by(|a: Str, b: Str| {
    let ca = m.get(a).unwrap_or(0);
    let cb = m.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let n = keys.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    let k = keys[i];
    lines.push(k + " " + m.get(k).unwrap_or(0).to_str());
  }
  Ok(lines.join("\n"))
}

struct Tot { region: Str, qty: Int, cents: Int }

fn fmt(cents: Int) -> Str {
  let neg = cents < 0;
  let a = if neg { -cents } else { cents };
  let d = a / 100;
  let c = a % 100;
  let cs = if c < 10 { "0" + c.to_str() } else { c.to_str() };
  let sign = if neg { "-" } else { "" };
  sign + d.to_str() + "." + cs
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut qty: Map<Str, Int> = Map::new();
  let mut rev: Map<Str, Int> = Map::new();
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 {
      skipped += 1;
      continue;
    }
    let Some(q) = parts[3].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let Some(u) = parts[4].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let region = parts[1].trim();
    qty.insert(region, qty.get(region).unwrap_or(0) + q);
    rev.insert(region, rev.get(region).unwrap_or(0) + q * u);
  }
  let mut rows: List<Tot> = [];
  for k in qty.keys() {
    rows.push(Tot { region: k, qty: qty.get(k).unwrap_or(0), cents: rev.get(k).unwrap_or(0) });
  }
  rows.sort_by(|a, b| a.cents > b.cents || (a.cents == b.cents && a.region < b.region));
  let mut out = "";
  for r in rows {
    out = out + r.region + " " + r.qty.to_str() + " " + fmt(r.cents) + "\n";
  }
  out = out + "skipped " + skipped.to_str() + "\n";
  Ok(out)
}

struct E { ip: Str, n: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for raw in text.lines() {
    let line = raw.trim();
    let parts = line.split("\"");
    if parts.len() != 3 { continue; }
    let head = parts[0].trim();
    if !head.ends_with("]") { continue; }
    let ip = head.split(" ")[0];
    if ip.len() == 0 { continue; }
    let words = parts[1].split(" ");
    if words.len() != 3 { continue; }
    let fields = parts[2].trim().split(" ");
    if fields.len() != 2 { continue; }
    let Some(status) = fields[0].parse_int() else { continue; };
    let size = if fields[1] == "-" {
      0
    } else {
      match fields[1].parse_int() {
        Some(n) => n,
        None => -1,
      }
    };
    if size < 0 { continue; }
    let full = words[1];
    let path = match full.find("?") {
      Some(i) => full.slice(0, i),
      None => full,
    };
    statuses.insert(status, statuses.get(status).unwrap_or(0) + 1);
    total += size;
    paths.insert(path, paths.get(path).unwrap_or(0) + 1);
    if status >= 500 && status <= 599 {
      errs.insert(ip, errs.get(ip).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > best_n {
      best = p;
      best_n = c;
    }
  }
  if best_n > 0 {
    out.push("top " + best + " " + best_n.to_str());
  }
  let mut es: List<E> = [];
  for ip in errs.keys() {
    es.push(E { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  es.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for e in es {
    out.push("errors " + e.ip + " " + e.n.to_str());
  }
  Ok(out.join("\n"))
}

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut t = 0;
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t += q * p;
  }
  t
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = match input.read("orders.json") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.json"),
  };
  let doc = bytes.to_str().parse_json()?;
  let orders = doc.as_list().unwrap_or([]);
  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut rn = 0;
  let mut rt = 0;
  let mut pn = 0;
  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    if status == "paid" {
      let cust = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
      let c = counts.get(cust).unwrap_or(0);
      counts.insert(cust, c + 1);
      let t = totals.get(cust).unwrap_or(0);
      totals.insert(cust, t + order_total(o));
    } else if status == "refunded" {
      rn += 1;
      rt += order_total(o);
    } else if status == "pending" {
      pn += 1;
    }
  }
  let mut out: Str = "";
  for c in counts.keys() {
    out = out + c + " " + counts.get(c).unwrap_or(0).to_str() + " " + totals.get(c).unwrap_or(0).to_str() + "\n";
  }
  out = out + "refunded " + rn.to_str() + " " + rt.to_str() + "\n";
  out = out + "pending " + pn.to_str() + "\n";
  Ok(out)
}

fn normalize(s: Str) -> Option<Str> {
  let parts = s.split("@");
  if parts.len() != 2 { return None; }
  let mut local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
    return None;
  }
  if domain == "gmail.com" {
    if let Some(i) = local.find("+") {
      local = local.slice(0, i);
    }
    local = local.replace(".", "");
  }
  Some(local + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for line in text.lines() {
    let s = line.trim().to_lowercase();
    if s.len() == 0 { continue; }
    match normalize(s) {
      Some(addr) => seen.insert(addr, true),
      None => invalid += 1,
    }
  }
  let mut out = "";
  for k in seen.keys() {
    out = out + k + "\n";
  }
  out = out + "invalid " + invalid.to_str() + "\n";
  Ok(out)
}

fn roman_val(c: Str) -> Int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn to_roman(n: Int) -> Str {
  let vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut r = "";
  let mut x = n;
  for i in 0..13 {
    while x >= vals[i] {
      r = r + syms[i];
      x -= vals[i];
    }
  }
  r
}

fn from_roman(s: Str) -> Option<Int> {
  let cs = s.chars();
  let mut vs: List<Int> = [];
  for c in cs {
    let v = roman_val(c);
    if v == 0 { return None; }
    vs.push(v);
  }
  let n = vs.len();
  let mut sum = 0;
  for i in 0..n {
    if i + 1 < n && vs[i] < vs[i + 1] {
      sum -= vs[i];
    } else {
      sum += vs[i];
    }
  }
  if sum >= 1 && sum <= 3999 && to_roman(sum) == s {
    Some(sum)
  } else {
    None
  }
}

fn all_digits(s: Str) -> Bool {
  for b in s.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn convert(line: Str) -> Str {
  if all_digits(line) {
    match line.parse_int() {
      Some(n) => {
        if n >= 1 && n <= 3999 { to_roman(n) } else { "invalid" }
      },
      None => "invalid",
    }
  } else {
    match from_roman(line) {
      Some(n) => n.to_str(),
      None => "invalid",
    }
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    out.push(line + " = " + convert(line));
  }
  Ok(out.join("\n"))
}

fn check(line: Str) -> Str {
  let chars = line.chars();
  let mut stack: List<Str> = [];
  let n = chars.len();
  for i in 0..n {
    let c = chars[i];
    if c == "(" {
      stack.push(")");
    } else if c == "[" {
      stack.push("]");
    } else if c == "{" {
      stack.push("}");
    } else if c == ")" || c == "]" || c == "}" {
      match stack.pop() {
        None => {
          return "col " + (i + 1).to_str() + ": unexpected " + c;
        },
        Some(x) => {
          if x != c {
            return "col " + (i + 1).to_str() + ": expected " + x + ", found " + c;
          }
        },
      }
    }
  }
  if stack.len() == 0 {
    "ok"
  } else {
    "unclosed " + stack[stack.len() - 1]
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

fn pct(t: List<Int>, p: Int) -> Int {
  let n = t.len();
  let idx = (p * n + 99) / 100;
  t[idx - 1]
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut m: Map<Str, List<Int>> = Map::new();
  for raw in text.lines() {
    let line = raw.trim();
    let parts = line.split(" ");
    if parts.len() != 3 { continue; }
    let Some(ms) = parts[2].parse_int() else { continue; };
    let key = parts[0] + " " + parts[1];
    let mut cur: List<Int> = m.get(key).unwrap_or([]);
    cur.push(ms);
    m.insert(key, cur);
  }
  let mut lines: List<Str> = [];
  for k in m.keys() {
    let mut ts: List<Int> = m.get(k).unwrap_or([]);
    ts.sort();
    let n = ts.len();
    lines.push(k + " count=" + n.to_str() + " p50=" + pct(ts, 50).to_str() + " p95=" + pct(ts, 95).to_str() + " max=" + ts[n - 1].to_str());
  }
  Ok(lines.join("\n"))
}

struct Road { a: Str, b: Str, w: Int }
struct Trip { a: Str, b: Str }
struct Adj { to: Int, w: Int }

fn dists(adj: List<List<Adj>>, n: Int, t: Int) -> List<Int> {
  let mut d: List<Int> = [];
  let mut done: List<Bool> = [];
  for i in 0..n {
    d.push(-1);
    done.push(false);
  }
  d[t] = 0;
  for k in 0..n {
    let mut best = -1;
    for i in 0..n {
      if !done[i] && d[i] >= 0 {
        if best < 0 || d[i] < d[best] { best = i; }
      }
    }
    if best < 0 { break; }
    done[best] = true;
    for e in adj[best] {
      let nd = d[best] + e.w;
      if d[e.to] < 0 || nd < d[e.to] { d[e.to] = nd; }
    }
  }
  d
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut roads: List<Road> = [];
  let mut trips: List<Trip> = [];
  for line in text.lines() {
    let t = line.replace("\t", " ").trim();
    if t.len() == 0 || t.starts_with("#") { continue; }
    let parts = t.split(" ").filter(|s| s.len() > 0);
    if parts.len() == 4 && parts[0] == "road" {
      let Some(w) = parts[3].parse_int() else { continue; };
      roads.push(Road { a: parts[1], b: parts[2], w: w });
    } else if parts.len() == 3 && parts[0] == "trip" {
      trips.push(Trip { a: parts[1], b: parts[2] });
    }
  }
  let mut ids: Map<Str, Int> = Map::new();
  let mut names: List<Str> = [];
  let mut all: List<Str> = [];
  for r in roads { all.push(r.a); all.push(r.b); }
  for t in trips { all.push(t.a); all.push(t.b); }
  for s in all {
    if ids.get(s).is_none() {
      ids.insert(s, names.len());
      names.push(s);
    }
  }
  let n = names.len();
  let mut adj: List<List<Adj>> = [];
  for i in 0..n {
    let e: List<Adj> = [];
    adj.push(e);
  }
  for r in roads {
    let a = ids.get(r.a).unwrap_or(0);
    let b = ids.get(r.b).unwrap_or(0);
    adj[a].push(Adj { to: b, w: r.w });
    adj[b].push(Adj { to: a, w: r.w });
  }
  let mut cache: Map<Int, List<Int>> = Map::new();
  let mut lines: List<Str> = [];
  for t in trips {
    let a = ids.get(t.a).unwrap_or(0);
    let b = ids.get(t.b).unwrap_or(0);
    if a == b {
      lines.push(t.a + " 0");
      continue;
    }
    let d = match cache.get(b) {
      Some(x) => x,
      None => {
        let x = dists(adj, n, b);
        cache.insert(b, x);
        x
      }
    };
    if d[a] < 0 {
      lines.push(t.a + " " + t.b + " unreachable");
      continue;
    }
    let mut cur = a;
    let mut path = names[a];
    while cur != b {
      let mut best = -1;
      for e in adj[cur] {
        if d[e.to] >= 0 && e.w + d[e.to] == d[cur] {
          if best < 0 || names[e.to] < names[best] { best = e.to; }
        }
      }
      cur = best;
      path = path + " -> " + names[cur];
    }
    lines.push(path + " " + d[a].to_str());
  }
  Ok(lines.join("\n"))
}

fn load(d: Dir, name: Str) -> Result<Json, Str> {
  let bytes = match d.read(name) {
    Ok(b) => b,
    Err(_) => return Err("cannot read " + name),
  };
  bytes.to_str().parse_json()
}

fn merge(b: Json, o: Json) -> Json {
  match b {
    Json::Obj(bm) => match o {
      Json::Obj(om) => {
        let mut r = bm;
        for k in om.keys() {
          let v = om.get(k).unwrap_or(Json::Null);
          match v {
            Json::Null => { r.remove(k); }
            _ => {
              let nv = match r.get(k) {
                Some(bv) => merge(bv, v),
                None => v,
              };
              r.insert(k, nv);
            }
          }
        }
        Json::Obj(r)
      }
      _ => o,
    },
    _ => o,
  }
}

fn join(path: Str, k: Str) -> Str {
  if path == "" { k } else { path + "." + k }
}

fn flatten(j: Json, path: Str, acc: Map<Str, Str>) -> Map<Str, Str> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.insert(path, "{}");
      } else {
        for k in m.keys() {
          let child = m.get(k).unwrap_or(Json::Null);
          out = flatten(child, join(path, k), out);
        }
      }
    }
    Json::Arr(a) => {
      if a.len() == 0 {
        out.insert(path, "[]");
      } else {
        let mut i = 0;
        for x in a {
          out = flatten(x, join(path, i.to_str()), out);
          i += 1;
        }
      }
    }
    _ => { out.insert(path, j.to_json()); }
  }
  out
}

fn main(input: Dir) -> Result<Str, Str> {
  let base = load(input, "base.json")?;
  let over = load(input, "override.json")?;
  let merged = merge(base, over);
  let start: Map<Str, Str> = Map::new();
  let m = flatten(merged, "", start);
  let mut lines: List<Str> = [];
  for k in m.keys() {
    lines.push(k + "=" + m.get(k).unwrap_or(""));
  }
  Ok(lines.join("\n"))
}

fn render(ls: List<Str>) -> Str {
  if ls.len() == 0 {
    return "";
  }
  ls.join("\n") + "\n"
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut errs: List<Str> = [];
  let mut warns: List<Str> = [];
  let mut infos: List<Str> = [];
  let mut other = 0;
  for line in text.lines() {
    if line.trim() == "" {
      continue;
    }
    let parts = line.split(" ");
    if parts.len() < 3 {
      other += 1;
      continue;
    }
    let lv = parts[1].to_uppercase();
    if lv == "ERROR" {
      errs.push(line);
    } else if lv == "WARN" || lv == "WARNING" {
      warns.push(line);
    } else if lv == "INFO" {
      infos.push(line);
    } else {
      other += 1;
    }
  }
  out.write("error.log", render(errs).to_bytes())?;
  out.write("warn.log", render(warns).to_bytes())?;
  out.write("info.log", render(infos).to_bytes())?;
  Ok("error " + errs.len().to_str() + "\nwarn " + warns.len().to_str() + "\ninfo " + infos.len().to_str() + "\nother " + other.to_str() + "\n")
}

fn walk(d: Dir, dir: Str, acc: List<Str>) -> Result<List<Str>, IoErr> {
  let mut a = acc;
  let prefix = if dir == "" { "" } else { dir + "/" };
  let names = d.list(dir)?;
  for name in names {
    if name.ends_with("/") {
      let sub = prefix + name.slice(0, name.len() - 1);
      a = walk(d, sub, a)?;
    } else {
      a.push(prefix + name);
    }
  }
  Ok(a)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let empty: List<Str> = [];
  let mut paths = walk(input, "", empty)?;
  paths.sort();
  let mut csv = "path,bytes,lines\n";
  let mut total = 0;
  let mut count = 0;
  for p in paths {
    let data = input.read(p)?;
    let size = data.len();
    let mut n = 0;
    for b in data {
      if b == 10 { n += 1; }
    }
    if size > 0 && data[size - 1] != 10 { n += 1; }
    csv = csv + p + "," + size.to_str() + "," + n.to_str() + "\n";
    total += size;
    count += 1;
  }
  out.create("index.csv", csv.to_bytes())?;
  Ok("files " + count.to_str() + " bytes " + total.to_str())
}

fn parse_line(line: Str) -> List<Str> {
  let chars = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < chars.len() {
    let c = chars[i];
    if inq {
      if c == "\"" {
        if i + 1 < chars.len() && chars[i + 1] == "\"" {
          cur = cur + "\"";
          i += 1;
        } else {
          inq = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\"" {
        inq = true;
      } else if c == "," {
        fields.push(cur);
        cur = "";
      } else {
        cur = cur + c;
      }
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn build(fields: List<Str>) -> Option<Json> {
  if fields.len() != 5 { return None; }
  let id = fields[0].parse_int()?;
  let act = fields[3].to_lowercase();
  let active = act == "yes" || act == "true" || act == "1";
  let mut tags: List<Json> = [];
  for t in fields[4].split(";") {
    let s = t.trim();
    if s.len() > 0 { tags.push(Json::Str(s)); }
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("name", Json::Str(fields[1]));
  m.insert("email", Json::Str(fields[2]));
  m.insert("active", Json::Bool(active));
  m.insert("tags", Json::Arr(tags));
  Some(Json::Obj(m))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim().len() == 0 { continue; }
    match build(parse_line(line)) {
      Some(j) => rows.push(j),
      None => skipped += 1,
    }
  }
  let n = rows.len();
  out.create("users.json", Json::Arr(rows).to_json().to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn normalize(name: Str) -> Str {
  let lower = name.to_lowercase();
  let mut ob = "".to_bytes();
  let mut pend = false;
  for b in lower.to_bytes() {
    if (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 46 {
      if pend && ob.len() > 0 {
        ob.push(45);
      }
      pend = false;
      ob.push(b);
    } else {
      pend = true;
    }
  }
  ob.to_str()
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut names = input.list("")?;
  names.sort();
  let mut taken: Map<Str, Bool> = Map::new();
  let mut lines: List<Str> = [];
  for name in names {
    let new_name = normalize(name);
    if new_name.len() == 0 || taken.get(new_name).is_some() {
      lines.push(name + " skipped");
    } else {
      let data = input.read(name)?;
      out.create(new_name, data)?;
      taken.insert(new_name, true);
      lines.push(name + " -> " + new_name);
    }
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  if !name.starts_with("part-") || !name.ends_with(".txt") { return false; }
  if name.len() <= 9 { return false; }
  let mid = name.slice(5, name.len() - 4);
  for c in mid.chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    if line.trim() == "" { continue; }
    vals.push(line.parse_int()?);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut all: List<Int> = [];
  let mut parts = 0;
  let mut corrupt = 0;
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    let text = input.read(name)?.to_str();
    match parse_part(text) {
      Some(vals) => {
        for v in vals { all.push(v); }
      },
      None => corrupt += 1,
    }
  }
  all.sort();
  let mut lines: List<Str> = [];
  let mut have = false;
  let mut last = 0;
  for v in all {
    if have && v == last { continue; }
    have = true;
    last = v;
    lines.push(v.to_str());
  }
  let count = lines.len();
  let body = if count > 0 { lines.join("\n") + "\n" } else { "" };
  out.create("merged.txt", body.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + count.to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let mut names = src.list("")?;
  names.sort();
  let dnames = dst.list("")?;
  let mut out = "";
  for name in names {
    let data = src.read(name)?;
    if dst.exists(name)? {
      let old = dst.read(name)?;
      if old == data {
        out = out + "same " + name + "\n";
      } else {
        dst.write(name, data)?;
        out = out + "updated " + name + "\n";
      }
    } else {
      dst.write(name, data)?;
      out = out + "added " + name + "\n";
    }
  }
  let mut kept = 0;
  for d in dnames {
    if !names.contains(d) {
      kept += 1;
    }
  }
  out = out + "kept " + kept.to_str() + "\n";
  Ok(out)
}

struct Entry { page: Str, total: Int }

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let bytes = match input.read("visits.txt") {
    Ok(b) => b,
    Err(_) => return Err("read failed"),
  };
  let text = bytes.to_str();
  let mut local: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let n = local.get(p).unwrap_or(0);
    local.insert(p, n + 1);
  }
  for p in local.keys() {
    let n = local.get(p).unwrap_or(0);
    match counts.add(p, n) {
      Ok(_) => {},
      Err(_) => return Err("kv add failed"),
    }
  }
  let keys = match counts.keys("") {
    Ok(k) => k,
    Err(_) => return Err("kv keys failed"),
  };
  let mut entries: List<Entry> = [];
  for k in keys {
    let v = match counts.get(k) {
      Ok(o) => o,
      Err(_) => return Err("kv get failed"),
    };
    let Some(b) = v else { continue; };
    let total = b.to_str().parse_int().unwrap_or(0);
    entries.push(Entry { page: k, total: total });
  }
  entries.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));
  let mut lines: List<Str> = [];
  for e in entries {
    lines.push(e.page + " " + e.total.to_str());
  }
  Ok(lines.join("\n"))
}

fn key(id: Str) -> Str {
  "user:" + id
}

fn process(users: Kv, raw: Str) -> Result<Str, KvErr> {
  let line = raw.trim();
  if line == "" { return Ok(""); }
  let parts = line.split(" ");
  let n = parts.len();
  let cmd = parts[0];
  if cmd == "put" && n == 4 {
    let id = parts[1];
    users.set(key(id), (parts[2] + " " + parts[3]).to_bytes())?;
    return Ok("ok " + id);
  }
  if cmd == "rename" && n == 3 {
    let id = parts[1];
    let got = users.get(key(id))?;
    return match got {
      None => Ok("missing " + id),
      Some(b) => {
        let fields = b.to_str().split(" ");
        users.set(key(id), (parts[2] + " " + fields[1]).to_bytes())?;
        Ok("ok " + id)
      }
    };
  }
  if cmd == "get" && n == 2 {
    let id = parts[1];
    let got = users.get(key(id))?;
    return match got {
      None => Ok("missing " + id),
      Some(b) => {
        let fields = b.to_str().split(" ");
        Ok("{\"id\":" + Json::Str(id).to_json() + ",\"name\":" + Json::Str(fields[0]).to_json() + ",\"email\":" + Json::Str(fields[1]).to_json() + "}")
      }
    };
  }
  if cmd == "del" && n == 2 {
    let id = parts[1];
    let got = users.get(key(id))?;
    return match got {
      None => Ok("missing " + id),
      Some(_) => {
        users.delete(key(id))?;
        Ok("ok " + id)
      }
    };
  }
  if cmd == "count" && n == 1 {
    let ks = users.keys("user:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok("bad " + line)
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  let bytes = match input.read("commands.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read commands.txt"),
  };
  let mut out = "";
  for line in bytes.to_str().lines() {
    let r = match process(users, line) {
      Ok(s) => s,
      Err(_) => return Err("kv error"),
    };
    if r != "" {
      out = out + r + "\n";
    }
  }
  Ok(out)
}

struct Ev { id: Str, account: Str, cents: Int }

fn parse(line: Str) -> Option<Ev> {
  let Ok(j) = line.parse_json() else { return None; };
  let Some(id) = j.get("id").and_then(|x| x.as_str()) else { return None; };
  let Some(account) = j.get("account").and_then(|x| x.as_str()) else { return None; };
  let Some(cents) = j.get("cents").and_then(|x| x.as_int()) else { return None; };
  Some(Ev { id: id, account: account, cents: cents })
}

// 0 applied, 1 duplicate
fn apply(state: Kv, ev: Ev) -> Result<Int, Str> {
  let claimed = state.swap("seen/" + ev.id, None, Some("1".to_bytes())).map_err(|e| "kv error")?;
  if claimed {
    state.add("bal/" + ev.account, ev.cents).map_err(|e| "kv error")?;
    Ok(0)
  } else {
    Ok(1)
  }
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let text = input.read("events.jsonl").map_err(|e| "cannot read events.jsonl")?.to_str();
  let mut applied = 0;
  let mut dup = 0;
  let mut rejected = 0;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let Some(ev) = parse(line) else { rejected += 1; continue; };
    let r = apply(state, ev)?;
    if r == 0 { applied += 1; } else { dup += 1; }
  }
  let mut out: List<Str> = [];
  out.push("applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rejected.to_str());
  let mut after: Option<Str> = None;
  loop {
    let page = state.scan("bal/", after, 1000).map_err(|e| "kv error")?;
    for e in page {
      let acct = e.key.slice(4, e.key.len());
      out.push(acct + " " + e.value.to_str());
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(out.join("\n") + "\n")
}

fn decide(limits: Kv, secs: Int, client: Str) -> Result<Bool, KvErr> {
  let key = (secs / 60).to_str() + "|" + client;
  let cur = match limits.get(key)? {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  };
  if cur >= 3 {
    return Ok(false);
  }
  limits.set(key, (cur + 1).to_str().to_bytes())?;
  Ok(true)
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let bytes = match input.read("requests.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read requests.txt"),
  };
  let text = bytes.to_str();
  let mut out = "";
  for line in text.lines() {
    let norm = line.replace("\t", " ").replace("\r", " ").trim();
    let mut fields: List<Str> = [];
    for p in norm.split(" ") {
      if p.len() > 0 {
        fields.push(p);
      }
    }
    if fields.len() != 2 {
      continue;
    }
    let Some(secs) = fields[0].parse_int() else { continue; };
    let client = fields[1];
    let ok = match decide(limits, secs, client) {
      Ok(v) => v,
      Err(_) => return Err("kv error"),
    };
    let verdict = if ok { "allow" } else { "deny" };
    out = out + secs.to_str() + " " + client + " " + verdict + "\n";
  }
  Ok(out)
}

struct Player { name: Str, pts: Int, gp: Int }

fn get_int(board: Kv, k: Str) -> Result<Int, KvErr> {
  match board.get(k)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn bump(board: Kv, name: Str, pts: Int) -> Result<(), KvErr> {
  board.add("pts:" + name, pts)?;
  board.add("gp:" + name, 1)?;
  Ok(())
}

fn better(a: Player, b: Player) -> Bool {
  if a.pts != b.pts { return a.pts > b.pts; }
  if a.gp != b.gp { return a.gp < b.gp; }
  a.name < b.name
}

fn apply(board: Kv, text: Str) -> Result<Str, KvErr> {
  for raw in text.lines() {
    let line = raw.trim();
    let parts = line.split(" ");
    if parts.len() == 2 {
      if parts[0].len() > 0 && parts[1].len() > 0 {
        bump(board, parts[0], 3)?;
        bump(board, parts[1], 0)?;
      }
    } else if parts.len() == 3 {
      if parts[0].len() > 0 && parts[1].len() > 0 && parts[2] == "draw" {
        bump(board, parts[0], 1)?;
        bump(board, parts[1], 1)?;
      }
    }
  }
  let ks = board.keys("pts:")?;
  let mut players: List<Player> = [];
  for k in ks {
    let name = k.strip_prefix("pts:").unwrap_or(k);
    let pts = get_int(board, "pts:" + name)?;
    let gp = get_int(board, "gp:" + name)?;
    players.push(Player { name: name, pts: pts, gp: gp });
  }
  players.sort_by(better);
  let mut lines: List<Str> = [];
  let n = players.len().min(3);
  for i in 0..n {
    let p = players[i];
    lines.push((i + 1).to_str() + ". " + p.name + " " + p.pts.to_str() + " " + p.gp.to_str());
  }
  Ok(lines.join("\n"))
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let data = match input.read("games.txt") {
    Ok(b) => b,
    Err(IoErr::NotFound) => "".to_bytes(),
    Err(_) => return Err("read failed"),
  };
  match apply(board, data.to_str()) {
    Ok(s) => Ok(s),
    Err(_) => Err("kv error"),
  }
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  let created = shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []);
  if created.is_err() { return Err("cannot create schema"); }

  let bytes = match input.read("orders.csv") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.csv"),
  };
  let lines = bytes.to_str().lines();
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;

  for i in 0..lines.len() {
    if i == 0 { continue; }
    let line = lines[i].trim();
    if line.len() == 0 { continue; }
    let parts = line.split(",");
    if parts.len() != 5 { rejected += 1; continue; }
    let Some(id) = parts[0].trim().parse_int() else { rejected += 1; continue; };
    let Some(qty) = parts[3].trim().parse_int() else { rejected += 1; continue; };
    let Some(cents) = parts[4].trim().parse_int() else { rejected += 1; continue; };
    let r = shop.exec(
      "INSERT INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(id), SqlValue::Text(parts[1].trim()), SqlValue::Text(parts[2].trim()), SqlValue::Int(qty), SqlValue::Int(cents)]
    );
    match r {
      Ok(_) => imported += 1,
      Err(DbErr::Constraint(_)) => skipped += 1,
      Err(_) => return Err("database error"),
    }
  }

  let rows = match shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ) {
    Ok(r) => r,
    Err(_) => return Err("query failed"),
  };

  let mut out = "imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str();
  for row in rows {
    if row.len() < 3 { continue; }
    out = out + "\n" + text_of(row[0]) + " " + int_of(row[1]).to_str() + " " + int_of(row[2]).to_str();
  }
  Ok(out)
}

struct Country {
  name: Str,
  customers: Int,
  orders: Int,
  rev: Int,
  top_name: Str,
  top_rev: Int,
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let rows = shop.query(
    "SELECT c.id, c.name, c.country, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01' GROUP BY c.id, c.name, c.country ORDER BY c.id",
    [],
  )?;
  let mut m: Map<Str, Country> = Map::new();
  let mut total_orders = 0;
  let mut total_rev = 0;
  for r in rows {
    let name = text_of(r[1]);
    let country = text_of(r[2]);
    let n = int_of(r[3]);
    let rev = int_of(r[4]);
    total_orders += n;
    total_rev += rev;
    let mut c = match m.get(country) {
      Some(c) => c,
      None => Country { name: country, customers: 0, orders: 0, rev: 0, top_name: "", top_rev: -1 },
    };
    c.customers += 1;
    c.orders += n;
    c.rev += rev;
    if rev > c.top_rev {
      c.top_rev = rev;
      c.top_name = name;
    }
    m.insert(country, c);
  }
  let mut list: List<Country> = [];
  for k in m.keys() {
    if let Some(c) = m.get(k) {
      list.push(c);
    }
  }
  list.sort_by(|a, b| a.rev > b.rev || (a.rev == b.rev && a.name < b.name));
  let mut lines: List<Str> = [];
  for c in list {
    lines.push(c.name + " customers=" + c.customers.to_str() + " orders=" + c.orders.to_str() + " revenue=" + c.rev.to_str() + " top=" + c.top_name);
  }
  lines.push("total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str());
  Ok(lines.join("\n"))
}

struct Move { sku: Str, delta: Int }
struct Batch { name: Str, moves: List<Move>, bad: Bool }

fn amount(rest: Str) -> Option<Int> {
  if rest.starts_with("+") || rest.starts_with("-") { return None; }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  Some(n)
}

fn parse_move(t: Str) -> Option<Move> {
  let parts = t.split(" ");
  if parts.len() != 2 { return None; }
  let tok = parts[1];
  if let Some(r) = tok.strip_prefix("+") {
    let n = amount(r)?;
    return Some(Move { sku: parts[0], delta: n });
  }
  if let Some(r) = tok.strip_prefix("-") {
    let n = amount(r)?;
    return Some(Move { sku: parts[0], delta: 0 - n });
  }
  None
}

fn ensure(stock: Db) -> Result<(), Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS batches (name TEXT PRIMARY KEY)", []).map_err(|e| "db error")?;
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL CHECK (qty >= 0))", []).map_err(|e| "db error")?;
  Ok(())
}

fn run_batch(stock: Db, b: Batch) -> Result<Str, Str> {
  let rows = stock.query("SELECT 1 FROM batches WHERE name = ?", [SqlValue::Text(b.name)]).map_err(|e| "db error")?;
  if rows.len() > 0 { return Ok("skipped"); }
  if b.bad { return Ok("rejected"); }
  let mut stmts: List<Str> = ["INSERT INTO batches (name) VALUES (?)"];
  let mut params: List<List<SqlValue>> = [[SqlValue::Text(b.name)]];
  for m in b.moves {
    stmts.push("INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = qty + excluded.qty");
    params.push([SqlValue::Text(m.sku), SqlValue::Int(m.delta)]);
  }
  match stock.transaction(stmts, params) {
    Ok(_) => Ok("applied"),
    Err(DbErr::Constraint(_)) => Ok("rejected"),
    Err(_) => Err("db error"),
  }
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  ensure(stock)?;
  let text = input.read("moves.txt").map_err(|e| "read error")?.to_str();
  let mut batches: List<Batch> = [];
  for line in text.lines() {
    let t = line.trim();
    if t == "" { continue; }
    if t.starts_with("batch ") {
      let name = t.slice(6, t.len()).trim();
      batches.push(Batch { name: name, moves: [], bad: name == "" });
      continue;
    }
    if batches.len() == 0 { continue; }
    let idx = batches.len() - 1;
    match parse_move(t) {
      Some(m) => batches[idx].moves.push(m),
      None => batches[idx].bad = true,
    }
  }
  let mut out = "";
  for b in batches {
    let r = run_batch(stock, b)?;
    out = out + b.name + " " + r + "\n";
  }
  let rows = stock.query("SELECT sku, qty FROM stock WHERE qty != 0 ORDER BY sku", []).map_err(|e| "db error")?;
  for row in rows {
    let sku = match row[0] { SqlValue::Text(s) => s, _ => "" };
    let qty = match row[1] { SqlValue::Int(q) => q, _ => 0 };
    out = out + sku + " " + qty.to_str() + "\n";
  }
  Ok(out)
}

struct Move { sku: Str, delta: Int }
struct Batch { name: Str, moves: List<Move>, bad: Bool }

fn amount(rest: Str) -> Option<Int> {
  if rest.starts_with("+") || rest.starts_with("-") { return None; }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  Some(n)
}

fn parse_move(t: Str) -> Option<Move> {
  let parts = t.split(" ");
  if parts.len() != 2 { return None; }
  let tok = parts[1];
  if let Some(r) = tok.strip_prefix("+") {
    let n = amount(r)?;
    return Some(Move { sku: parts[0], delta: n });
  }
  if let Some(r) = tok.strip_prefix("-") {
    let n = amount(r)?;
    return Some(Move { sku: parts[0], delta: 0 - n });
  }
  None
}

fn ensure(stock: Db) -> Result<(), Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS batches (name TEXT PRIMARY KEY)", []).map_err(|e| "db error")?;
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL CHECK (qty >= 0))", []).map_err(|e| "db error")?;
  Ok(())
}

fn run_batch(stock: Db, b: Batch) -> Result<Str, Str> {
  let rows = stock.query("SELECT 1 FROM batches WHERE name = ?", [SqlValue::Text(b.name)]).map_err(|e| "db error")?;
  if rows.len() > 0 { return Ok("skipped"); }
  if b.bad { return Ok("rejected"); }
  let mut stmts: List<Str> = ["INSERT INTO batches (name) VALUES (?)"];
  let mut params: List<List<SqlValue>> = [[SqlValue::Text(b.name)]];
  for m in b.moves {
    stmts.push("INSERT OR IGNORE INTO stock (sku, qty) VALUES (?, 0)");
    params.push([SqlValue::Text(m.sku)]);
    stmts.push("UPDATE stock SET qty = qty + ? WHERE sku = ?");
    params.push([SqlValue::Int(m.delta), SqlValue::Text(m.sku)]);
  }
  match stock.transaction(stmts, params) {
    Ok(_) => Ok("applied"),
    Err(DbErr::Constraint(_)) => Ok("rejected"),
    Err(_) => Err("db error"),
  }
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  ensure(stock)?;
  let text = input.read("moves.txt").map_err(|e| "read error")?.to_str();
  let mut batches: List<Batch> = [];
  for line in text.lines() {
    let t = line.trim();
    if t == "" { continue; }
    if t.starts_with("batch ") {
      let name = t.slice(6, t.len()).trim();
      batches.push(Batch { name: name, moves: [], bad: name == "" });
      continue;
    }
    if batches.len() == 0 { continue; }
    let idx = batches.len() - 1;
    match parse_move(t) {
      Some(m) => batches[idx].moves.push(m),
      None => batches[idx].bad = true,
    }
  }
  let mut out = "";
  for b in batches {
    let r = run_batch(stock, b)?;
    out = out + b.name + " " + r + "\n";
  }
  let rows = stock.query("SELECT sku, qty FROM stock WHERE qty != 0 ORDER BY sku", []).map_err(|e| "db error")?;
  for row in rows {
    let sku = match row[0] { SqlValue::Text(s) => s, _ => "" };
    let qty = match row[1] { SqlValue::Int(q) => q, _ => 0 };
    out = out + sku + " " + qty.to_str() + "\n";
  }
  Ok(out)
}

fn process(crm: Db, email: Str, name: Str, phone: Str) -> Result<Int, Str> {
  let rows = match crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]) {
    Ok(r) => r,
    Err(_) => return Err("db error"),
  };
  if rows.len() == 0 {
    match crm.exec("INSERT INTO contacts(email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]) {
      Ok(_) => Ok(0),
      Err(_) => Err("db error"),
    }
  } else {
    let row = rows[0];
    let same = row[0] == SqlValue::Text(name) && row[1] == SqlValue::Text(phone);
    if same {
      Ok(2)
    } else {
      match crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]) {
        Ok(_) => Ok(1),
        Err(_) => Err("db error"),
      }
    }
  }
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  match crm.exec("CREATE TABLE IF NOT EXISTS contacts(email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []) {
    Ok(_) => {},
    Err(_) => return Err("db error"),
  }
  let bytes = match input.read("contacts.csv") {
    Ok(b) => b,
    Err(_) => return Err("cannot read contacts.csv"),
  };
  let text = bytes.to_str();
  let mut ins = 0;
  let mut upd = 0;
  let mut same = 0;
  let mut rej = 0;
  let mut header_seen = false;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    if !header_seen {
      header_seen = true;
      continue;
    }
    let parts = line.split(",");
    if parts.len() != 3 {
      rej += 1;
      continue;
    }
    let email = parts[0].trim().to_lowercase();
    if !email.contains("@") {
      rej += 1;
      continue;
    }
    let code = process(crm, email, parts[1].trim(), parts[2].trim())?;
    match code {
      0 => ins += 1,
      1 => upd += 1,
      _ => same += 1,
    }
  }
  let total_rows = match crm.query("SELECT COUNT(*) FROM contacts", []) {
    Ok(r) => r,
    Err(_) => return Err("db error"),
  };
  let mut total = 0;
  if total_rows.len() > 0 {
    total = match total_rows[0][0] {
      SqlValue::Int(n) => n,
      _ => 0,
    };
  }
  let missing = match crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", []) {
    Ok(r) => r,
    Err(_) => return Err("db error"),
  };
  let mut out = "inserted " + ins.to_str() + " updated " + upd.to_str() + " unchanged " + same.to_str() + " rejected " + rej.to_str() + "\n";
  out = out + "contacts " + total.to_str() + "\n";
  for r in missing {
    if let SqlValue::Text(e) = r[0] {
      out = out + "missing phone: " + e + "\n";
    }
  }
  Ok(out)
}

struct Row { name: Str, count: Int }

fn respond(res: Outgoing, status: Int, body: Str) -> Result<Str, WebErr> {
  res.send(status, ["content-type"], ["application/json"], body.to_bytes())?;
  Ok("")
}

fn valid(name: Str) -> Bool {
  let n = name.len();
  if n < 1 || n > 32 { return false; }
  for b in name.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 45;
    if !ok { return false; }
  }
  true
}

fn entry(name: Str, count: Int) -> Str {
  "{\"name\":" + Json::Str(name).to_json() + ",\"count\":" + count.to_str() + "}"
}

fn all_rows(counts: Kv) -> Result<List<Row>, KvErr> {
  let mut rows: List<Row> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c/", after, 1000)?;
    for e in page {
      let n = e.value.to_str().parse_int().unwrap_or(0);
      rows.push(Row { name: e.key.slice(2, e.key.len()), count: n });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(rows)
}

fn top(res: Outgoing, counts: Kv) -> Result<Str, WebErr> {
  let r = counts.scan("c/", None, 1);
  if r.is_err() { return respond(res, 500, "{\"error\":\"internal\"}"); }
  let all = all_rows(counts);
  let mut rows: List<Row> = match all {
    Ok(v) => v,
    Err(_) => { return respond(res, 500, "{\"error\":\"internal\"}"); }
  };
  rows.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  let mut parts: List<Str> = [];
  let mut i = 0;
  while i < rows.len() && i < 3 {
    parts.push(entry(rows[i].name, rows[i].count));
    i += 1;
  }
  respond(res, 200, "[" + parts.join(",") + "]")
}

fn hit(res: Outgoing, counts: Kv, name: Str) -> Result<Str, WebErr> {
  if !valid(name) { return respond(res, 400, "{\"error\":\"bad name\"}"); }
  match counts.add("c/" + name, 1) {
    Ok(n) => respond(res, 200, entry(name, n)),
    Err(_) => respond(res, 500, "{\"error\":\"internal\"}"),
  }
}

fn count(res: Outgoing, counts: Kv, name: Str) -> Result<Str, WebErr> {
  if !valid(name) { return respond(res, 400, "{\"error\":\"bad name\"}"); }
  match counts.get("c/" + name) {
    Ok(Some(b)) => respond(res, 200, entry(name, b.to_str().parse_int().unwrap_or(0))),
    Ok(None) => respond(res, 200, entry(name, 0)),
    Err(_) => respond(res, 500, "{\"error\":\"internal\"}"),
  }
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, WebErr> {
  let m = req.method();
  let t = req.target();
  if m == "POST" {
    if let Some(n) = t.strip_prefix("/hit/") {
      return hit(res, counts, n);
    }
  }
  if m == "GET" {
    if t == "/top" { return top(res, counts); }
    if let Some(n) = t.strip_prefix("/count/") {
      return count(res, counts, n);
    }
  }
  respond(res, 404, "{\"error\":\"not found\"}")
}

struct Todo { id: Int, title: Str, done: Bool }
struct Resp { status: Int, body: Str }

fn todo_json(t: Todo) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(t.id));
  m.insert("title", Json::Str(t.title));
  m.insert("done", Json::Bool(t.done));
  Json::Obj(m)
}

fn err_body(msg: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m).to_json()
}

fn failure(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: err_body(msg) }
}

fn not_found() -> Resp {
  failure(404, "not found")
}

fn decode(b: Bytes) -> Option<Todo> {
  let j = b.to_str().parse_json().ok()?;
  let id = j.get("id").and_then(|x| x.as_int())?;
  let title = j.get("title").and_then(|x| x.as_str())?;
  let done = j.get("done").and_then(|x| x.as_bool())?;
  Some(Todo { id: id, title: title, done: done })
}

fn apply_patch(t0: Todo, j: Json) -> Option<Todo> {
  let Some(_) = j.as_map() else { return None; };
  let mut t = t0;
  match j.get("title") {
    None => {},
    Some(v) => {
      let Some(s) = v.as_str() else { return None; };
      let s2 = s.trim();
      if s2.len() == 0 { return None; }
      t.title = s2;
    },
  }
  match j.get("done") {
    None => {},
    Some(v) => {
      let Some(b) = v.as_bool() else { return None; };
      t.done = b;
    },
  }
  Some(t)
}

fn create(body: Bytes, store: Kv) -> Result<Resp, KvErr> {
  let Ok(j) = body.to_str().parse_json() else { return Ok(failure(400, "title required")); };
  let Some(raw) = j.get("title").and_then(|v| v.as_str()) else {
    return Ok(failure(400, "title required"));
  };
  let title = raw.trim();
  if title.len() == 0 { return Ok(failure(400, "title required")); }
  let id = store.add("seq", 1)?;
  let t = Todo { id: id, title: title, done: false };
  let j2 = todo_json(t).to_json();
  store.set("todo/" + id.to_str(), j2.to_bytes())?;
  Ok(Resp { status: 201, body: j2 })
}

fn list(query: Str, store: Kv) -> Result<Resp, KvErr> {
  let mut want: Option<Bool> = None;
  for p in query.split("&") {
    if p == "done=true" { want = Some(true); }
    if p == "done=false" { want = Some(false); }
  }
  let mut items: List<Todo> = [];
  let keys = store.keys("todo/")?;
  for k in keys {
    if let Some(raw) = store.get(k)? {
      if let Some(t) = decode(raw) {
        let keep = match want {
          None => true,
          Some(w) => t.done == w,
        };
        if keep { items.push(t); }
      }
    }
  }
  items.sort_by_key(|t| t.id);
  Ok(Resp { status: 200, body: Json::Arr(items.map(todo_json)).to_json() })
}

fn handle(req: Incoming, store: Kv) -> Result<Resp, KvErr> {
  let target = req.target();
  let mut path = target;
  let mut query = "";
  match target.find("?") {
    Some(i) => {
      path = target.slice(0, i);
      query = target.slice(i + 1, target.len());
    },
    None => {},
  }
  let method = req.method();
  if path == "/todos" {
    if method == "POST" { return create(req.body(), store); }
    if method == "GET" { return list(query, store); }
    return Ok(not_found());
  }
  let Some(rest) = path.strip_prefix("/todos/") else { return Ok(not_found()); };
  let Some(id) = rest.parse_int() else { return Ok(not_found()); };
  if id < 1 || id.to_str() != rest { return Ok(not_found()); }
  if method != "GET" && method != "PATCH" && method != "DELETE" { return Ok(not_found()); }
  let key = "todo/" + id.to_str();
  let Some(raw) = store.get(key)? else { return Ok(not_found()); };
  let Some(t) = decode(raw) else { return Ok(not_found()); };
  if method == "GET" {
    return Ok(Resp { status: 200, body: todo_json(t).to_json() });
  }
  if method == "DELETE" {
    store.delete(key)?;
    return Ok(Resp { status: 204, body: "" });
  }
  let Ok(j) = req.body().to_str().parse_json() else { return Ok(failure(400, "bad update")); };
  let Some(nt) = apply_patch(t, j) else { return Ok(failure(400, "bad update")); };
  let out = todo_json(nt).to_json();
  store.set(key, out.to_bytes())?;
  Ok(Resp { status: 200, body: out })
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Result<Str, WebErr> {
  let r = match handle(req, store) {
    Ok(r) => r,
    Err(_) => failure(500, "storage error"),
  };
  let mut names: List<Str> = [];
  let mut values: List<Str> = [];
  if r.status != 204 {
    names.push("content-type");
    values.push("application/json");
  }
  res.send(r.status, names, values, r.body.to_bytes())?;
  Ok("")
}

struct Resp { status: Int, body: Json }

struct NewNote { title: Str, body: Str, tags: List<Str> }

fn obj1(k: Str, v: Json) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m)
}

fn err(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: obj1("error", Json::Str(msg)) }
}

fn not_found() -> Resp { err(404, "not found") }

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(i) => i,
    _ => 0,
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn tags_of(v: SqlValue) -> List<Str> {
  let mut out: List<Str> = [];
  let items = text_of(v).parse_json().unwrap_or(Json::Arr([])).as_list().unwrap_or([]);
  for it in items {
    if let Some(s) = it.as_str() { out.push(s); }
  }
  out
}

fn note_json(row: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(int_of(row[0])));
  m.insert("title", Json::Str(text_of(row[1])));
  m.insert("body", Json::Str(text_of(row[2])));
  let mut tj: List<Json> = [];
  for t in tags_of(row[3]) { tj.push(Json::Str(t)); }
  m.insert("tags", Json::Arr(tj));
  Json::Obj(m)
}

fn parse_note(s: Str) -> Option<NewNote> {
  let doc = s.parse_json().ok()?;
  if doc.as_map().is_none() { return None; }
  let title = doc.get("title")?.as_str()?;
  if title.len() == 0 { return None; }
  let body = doc.get("body")?.as_str()?;
  let mut tags: List<Str> = [];
  if let Some(t) = doc.get("tags") {
    let items = t.as_list()?;
    for it in items {
      let s2 = it.as_str()?.to_lowercase();
      if !tags.contains(s2) { tags.push(s2); }
    }
  }
  Some(NewNote { title: title, body: body, tags: tags })
}

fn parse_id(s: Str) -> Option<Int> {
  let n = s.parse_int()?;
  if n >= 1 && n.to_str() == s { Some(n) } else { None }
}

fn query_param(query: Str, key: Str) -> Option<Str> {
  for part in query.split("&") {
    if let Some(v) = part.strip_prefix(key + "=") { return Some(v); }
  }
  None
}

fn create_note(body: Str, db: Db) -> Result<Resp, DbErr> {
  let Some(n) = parse_note(body) else { return Ok(err(400, "invalid note")); };
  let mut tj: List<Json> = [];
  for t in n.tags { tj.push(Json::Str(t)); }
  let rows = db.query(
    "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?) RETURNING id",
    [SqlValue::Text(n.title), SqlValue::Text(n.body), SqlValue::Text(Json::Arr(tj).to_json())])?;
  if rows.len() == 0 { return Ok(err(500, "internal error")); }
  Ok(Resp { status: 201, body: obj1("id", Json::Num(int_of(rows[0][0]))) })
}

fn list_notes(query: Str, db: Db) -> Result<Resp, DbErr> {
  let mut sql = "SELECT id, title, body, tags FROM notes";
  let mut params: List<SqlValue> = [];
  let q = query_param(query, "q");
  if let Some(w) = q {
    sql = sql + " WHERE (instr(title, ?) > 0 OR instr(body, ?) > 0)";
    params.push(SqlValue::Text(w));
    params.push(SqlValue::Text(w));
  }
  sql = sql + " ORDER BY id DESC";
  let rows = db.query(sql, params)?;
  let tag = query_param(query, "tag");
  let mut out: List<Json> = [];
  for row in rows {
    if let Some(t) = tag {
      if !tags_of(row[3]).contains(t.to_lowercase()) { continue; }
    }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(int_of(row[0])));
    m.insert("title", Json::Str(text_of(row[1])));
    out.push(Json::Obj(m));
  }
  Ok(Resp { status: 200, body: Json::Arr(out) })
}

fn get_note(id: Int, db: Db) -> Result<Resp, DbErr> {
  let rows = db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { return Ok(not_found()); }
  Ok(Resp { status: 200, body: note_json(rows[0]) })
}

fn delete_note(id: Int, db: Db) -> Result<Resp, DbErr> {
  let n = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if n == 0 { return Ok(not_found()); }
  Ok(Resp { status: 200, body: obj1("deleted", Json::Num(id)) })
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)", [])?;
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  if path == "/notes" {
    if method == "POST" {
      let text = req.body().to_str();
      return create_note(text, db);
    }
    if method == "GET" { return list_notes(query, db); }
    return Ok(not_found());
  }
  if let Some(rest) = path.strip_prefix("/notes/") {
    let Some(id) = parse_id(rest) else { return Ok(not_found()); };
    if method == "GET" { return get_note(id, db); }
    if method == "DELETE" { return delete_note(id, db); }
    return Ok(not_found());
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => err(500, "internal error"),
  };
  match res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes()) {
    _ => {}
  }
  ""
}

struct Station { id: Str, name: Str }

fn fmt(t: Int) -> Str {
  let neg = t < 0;
  let a = if neg { -t } else { t };
  let sign = if neg { "-" } else { "" };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn line(api: Http, s: Station) -> Str {
  let body = match api.get("/stations/" + s.id + "/readings") {
    Ok(b) => b,
    Err(_) => return s.name + " unavailable",
  };
  let Ok(doc) = body.to_str().parse_json() else {
    return s.name + " unavailable";
  };
  let rs = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut n = 0;
  let mut sum = 0;
  let mut lo = 0;
  let mut hi = 0;
  for r in rs {
    if let Some(t) = r.get("temp").and_then(|j| j.as_int()) {
      if n == 0 {
        lo = t;
        hi = t;
      } else {
        if t < lo { lo = t; }
        if t > hi { hi = t; }
      }
      n += 1;
      sum += t;
    }
  }
  if n == 0 {
    return s.name + " no data";
  }
  let avg = sum / n;
  s.name + " min=" + fmt(lo) + " max=" + fmt(hi) + " avg=" + fmt(avg) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let body = match api.get("/stations") {
    Ok(b) => b,
    Err(_) => return Err("stations unavailable"),
  };
  let doc = body.to_str().parse_json()?;
  let items = doc.get("stations").and_then(|j| j.as_list()).unwrap_or([]);
  let mut stations: List<Station> = [];
  for j in items {
    let Some(id) = j.get("id").and_then(|x| x.as_str()) else { continue; };
    let Some(name) = j.get("name").and_then(|x| x.as_str()) else { continue; };
    stations.push(Station { id: id, name: name });
  }
  stations.sort_by_key(|s| s.name);
  let mut lines: List<Str> = [];
  for s in stations {
    lines.push(line(api, s));
  }
  Ok(lines.join("\n"))
}

fn fetch(api: Http, page: Int) -> Result<Json, Str> {
  let body = match api.get("/orders?page=" + page.to_str()) {
    Ok(b) => b,
    Err(_) => return Err("GET failed for page " + page.to_str()),
  };
  body.to_str().parse_json()
}

fn main(api: Http) -> Result<Str, Str> {
  let mut page = 1;
  let mut count = 0;
  let mut refunded = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut have = false;
  let mut best_id = 0;
  let mut best_cents = 0;
  loop {
    let doc = fetch(api, page)?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in orders {
      count += 1;
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      if status == "refunded" { refunded += 1; }
      if status == "paid" {
        let id = o.get("id").and_then(|j| j.as_int()).unwrap_or(0);
        let cents = o.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
        let cur = o.get("currency").and_then(|j| j.as_str()).unwrap_or("");
        let prev = paid.get(cur).unwrap_or(0);
        paid.insert(cur, prev + cents);
        if !have || cents > best_cents || (cents == best_cents && id < best_id) {
          have = true;
          best_id = id;
          best_cents = cents;
        }
      }
    }
    let next = doc.get("next").and_then(|j| j.as_int());
    match next {
      Some(n) => page = n,
      None => break,
    }
  }
  let mut pc: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    pc.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("orders", Json::Num(count));
  m.insert("paid_cents", Json::Obj(pc));
  m.insert("refunded", Json::Num(refunded));
  if have {
    m.insert("largest", Json::Num(best_id));
  } else {
    m.insert("largest", Json::Null);
  }
  let body = Json::Obj(m).to_json().to_bytes();
  let r = match api.send("POST", "/summaries", ["content-type: application/json"], body, 0) {
    Ok(r) => r,
    Err(_) => return Err("POST failed"),
  };
  if r.status != 201 {
    return Err("status " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  match resp.get("id").and_then(|j| j.as_str()) {
    Some(id) => Ok(id),
    None => Err("no id in response"),
  }
}

fn touch(order: List<Str>, key: Str) -> List<Str> {
  let mut out: List<Str> = [key];
  for k in order {
    if k != key { out.push(k); }
  }
  out
}

fn without(order: List<Str>, key: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for k in order {
    if k != key { out.push(k); }
  }
  out
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(|e| "cannot read ops.txt")?.to_str();
  let lines = text.lines();
  let mut out: List<Str> = [];
  let mut order: List<Str> = [];
  let mut vals: Map<Str, Str> = Map::new();
  let mut hits = 0;
  let mut misses = 0;
  let mut evictions = 0;

  let raw = cache.get("state").map_err(|e| "kv error")?;
  if let Some(b) = raw {
    let j = b.to_str().parse_json()?;
    let ol: List<Json> = j.get("order").and_then(|x| x.as_list()).unwrap_or([]);
    for x in ol {
      if let Some(s) = x.as_str() { order.push(s); }
    }
    let m: Map<Str, Json> = j.get("vals").and_then(|x| x.as_map()).unwrap_or(Map::new());
    for k in m.keys() {
      let v = m.get(k).and_then(|x| x.as_str()).unwrap_or("");
      vals.insert(k, v);
    }
    hits = j.get("hits").and_then(|x| x.as_int()).unwrap_or(0);
    misses = j.get("misses").and_then(|x| x.as_int()).unwrap_or(0);
    evictions = j.get("evictions").and_then(|x| x.as_int()).unwrap_or(0);
  }

  if lines.len() == 0 { return Ok(""); }
  let first = lines[0].split(" ");
  let mut cap = 1;
  if first.len() >= 2 {
    cap = first[1].parse_int().unwrap_or(1);
  }

  while order.len() > cap {
    if let Some(k) = order.pop() {
      vals.remove(k);
      evictions += 1;
      out.push("evict " + k);
    }
  }

  for i in 1..lines.len() {
    let line = lines[i];
    let n = i + 1;
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    let op = parts[0];
    if op == "get" {
      if parts.len() != 2 || parts[1] == "" {
        out.push("bad line " + n.to_str());
      } else {
        let key = parts[1];
        match vals.get(key) {
          Some(v) => {
            hits += 1;
            order = touch(order, key);
            out.push(key + "=" + v);
          }
          None => {
            misses += 1;
            out.push(key + " miss");
          }
        }
      }
    } else if op == "put" {
      if parts.len() < 3 || parts[1] == "" {
        out.push("bad line " + n.to_str());
      } else {
        let key = parts[1];
        let value = line.slice(5 + key.len(), line.len());
        if value == "" {
          out.push("bad line " + n.to_str());
        } else {
          if vals.get(key).is_none() && order.len() >= cap {
            if let Some(k) = order.pop() {
              vals.remove(k);
              evictions += 1;
              out.push("evict " + k);
            }
          }
          vals.insert(key, value);
          order = touch(order, key);
        }
      }
    } else if op == "del" {
      if parts.len() != 2 || parts[1] == "" {
        out.push("bad line " + n.to_str());
      } else {
        let key = parts[1];
        if vals.get(key).is_some() {
          vals.remove(key);
          order = without(order, key);
        }
      }
    } else {
      out.push("bad line " + n.to_str());
    }
  }

  let mut vm: Map<Str, Json> = Map::new();
  for k in vals.keys() {
    vm.insert(k, Json::Str(vals.get(k).unwrap_or("")));
  }
  let mut root: Map<Str, Json> = Map::new();
  root.insert("order", Json::Arr(order.map(|k| Json::Str(k))));
  root.insert("vals", Json::Obj(vm));
  root.insert("hits", Json::Num(hits));
  root.insert("misses", Json::Num(misses));
  root.insert("evictions", Json::Num(evictions));
  cache.set("state", Json::Obj(root).to_json().to_bytes()).map_err(|e| "kv error")?;

  if order.len() == 0 {
    out.push("cache:");
  } else {
    out.push("cache: " + order.join(","));
  }
  out.push("stats hits " + hits.to_str() + " misses " + misses.to_str() + " evictions " + evictions.to_str());
  Ok(out.join("\n"))
}

fn parse_deps(j: Json) -> Option<List<Str>> {
  let items = j.as_list()?;
  let mut out: List<Str> = [];
  for it in items {
    let s = it.as_str()?;
    if !out.contains(s) { out.push(s); }
  }
  Some(out)
}

fn reach(start: Str, deps: Map<Str, List<Str>>) -> HashMap<Str, Bool> {
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut stack: List<Str> = [start];
  loop {
    let Some(c) = stack.pop() else { break; };
    let ds: List<Str> = deps.get(c).unwrap_or([]);
    for d in ds {
      if deps.get(d).is_some() && seen.get(d).is_none() {
        seen.insert(d, true);
        stack.push(d);
      }
    }
  }
  seen
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let doc = match text.parse_json() {
    Ok(d) => d,
    Err(_) => return Ok("error: not an object"),
  };
  let m = match doc.as_map() {
    Some(m) => m,
    None => return Ok("error: not an object"),
  };
  let mut deps: Map<Str, List<Str>> = Map::new();
  let mut invalid: List<Str> = [];
  for k in m.keys() {
    let Some(v) = m.get(k) else { continue; };
    match parse_deps(v) {
      Some(l) => { deps.insert(k, l); },
      None => { invalid.push(k); },
    }
  }
  let names = deps.keys();
  let mut lines: List<Str> = [];

  // stages
  let mut stage: Map<Str, Int> = Map::new();
  let mut changed = true;
  while changed {
    changed = false;
    for p in names {
      if stage.get(p).is_some() { continue; }
      let mut ok = true;
      let mut mx = 0;
      let ds: List<Str> = deps.get(p).unwrap_or([]);
      for d in ds {
        match stage.get(d) {
          Some(s) => { if s > mx { mx = s; } },
          None => { ok = false; },
        }
      }
      if ok {
        stage.insert(p, mx + 1);
        changed = true;
      }
    }
  }
  let mut maxs = 0;
  for p in names {
    let s = stage.get(p).unwrap_or(0);
    if s > maxs { maxs = s; }
  }
  for s in 1..(maxs + 1) {
    let mut ps: List<Str> = [];
    for p in names {
      if stage.get(p).unwrap_or(0) == s { ps.push(p); }
    }
    lines.push("stage " + s.to_str() + ": " + ps.join(", "));
  }

  // cycles
  let mut done: HashMap<Str, Bool> = HashMap::new();
  for p in names {
    if done.get(p).is_some() { continue; }
    let rp = reach(p, deps);
    if rp.get(p).is_none() { continue; }
    let mut grp: List<Str> = [];
    for q in names {
      if rp.get(q).is_some() {
        let rq = reach(q, deps);
        if rq.get(p).is_some() {
          grp.push(q);
          done.insert(q, true);
        }
      }
    }
    lines.push("cycle: " + grp.join(", "));
  }

  // missing
  let mut needed: Map<Str, List<Str>> = Map::new();
  for p in names {
    let ds: List<Str> = deps.get(p).unwrap_or([]);
    for d in ds {
      if deps.get(d).is_none() {
        let mut l: List<Str> = needed.get(d).unwrap_or([]);
        l.push(p);
        needed.insert(d, l);
      }
    }
  }
  for mname in needed.keys() {
    let l: List<Str> = needed.get(mname).unwrap_or([]);
    lines.push("missing: " + mname + " (needed by " + l.join(", ") + ")");
  }

  // invalid
  if invalid.len() > 0 {
    invalid.sort();
    lines.push("invalid: " + invalid.join(", "));
  }

  // blocked
  let mut blocked: List<Str> = [];
  for p in names {
    if stage.get(p).is_none() && done.get(p).is_none() { blocked.push(p); }
  }
  if blocked.len() > 0 {
    lines.push("blocked: " + blocked.join(", "));
  }

  lines.push("built " + stage.len().to_str() + " of " + names.len().to_str());
  Ok(lines.join("\n"))
}

struct Bk { room: Str, day: Str, s: Int, e: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Cf { start: Int, text: Str }

fn is_digits(s: Str) -> Bool {
  for c in s.chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_time(t: Str, end24: Bool) -> Option<Int> {
  let cs = t.chars();
  if cs.len() != 5 { return None; }
  if cs[2] != ":" { return None; }
  let hs = cs[0] + cs[1];
  let ms = cs[3] + cs[4];
  if !is_digits(hs) || !is_digits(ms) { return None; }
  let h = hs.parse_int()?;
  let m = ms.parse_int()?;
  if m > 59 { return None; }
  if h <= 23 {
    Some(h * 60 + m)
  } else if end24 && h == 24 && m == 0 {
    Some(1440)
  } else {
    None
  }
}

fn parse_line(line: Str) -> Option<Bk> {
  let f = line.split(",");
  if f.len() != 5 { return None; }
  let s = parse_time(f[2], false)?;
  let e = parse_time(f[3], true)?;
  if e <= s { return None; }
  Some(Bk { room: f[0], day: f[1], s: s, e: e, who: f[4] })
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(m: Int) -> Str {
  pad2(m / 60) + ":" + pad2(m % 60)
}

fn ivs(a: Int, b: Int) -> Str {
  fmt(a) + "-" + fmt(b)
}

fn day_report(bs: List<Bk>) -> Str {
  let mut sorted = bs;
  sorted.sort_by_key(|b| b.s);
  let mut busy: List<Iv> = [];
  for b in sorted {
    let n = busy.len();
    if n > 0 && b.s <= busy[n - 1].e {
      let cur = busy[n - 1];
      if b.e > cur.e {
        busy[n - 1] = Iv { s: cur.s, e: b.e };
      }
    } else {
      busy.push(Iv { s: b.s, e: b.e });
    }
  }
  let mut busy_strs: List<Str> = [];
  let mut free_strs: List<Str> = [];
  let mut pos = 540;
  for iv in busy {
    busy_strs.push(ivs(iv.s, iv.e));
    let gend = iv.s.min(1080);
    if gend - pos >= 30 {
      free_strs.push(ivs(pos, gend));
    }
    pos = pos.max(iv.e);
  }
  if 1080 - pos >= 30 {
    free_strs.push(ivs(pos, 1080));
  }
  let mut out = "  busy " + busy_strs.join(", ") + "\n";
  if free_strs.len() == 0 {
    out = out + "  free none\n";
  } else {
    out = out + "  free " + free_strs.join(", ") + "\n";
  }
  let mut cfs: List<Cf> = [];
  let n = sorted.len();
  for i in 0..n {
    for j in (i + 1)..n {
      let a = sorted[i];
      let b = sorted[j];
      let s = a.s.max(b.s);
      let e = a.e.min(b.e);
      if e > s {
        let mut names = [a.who, b.who];
        names.sort();
        cfs.push(Cf { start: s, text: names.join("/") + " " + ivs(s, e) });
      }
    }
  }
  cfs.sort_by(|x, y| x.start < y.start || (x.start == y.start && x.text < y.text));
  for c in cfs {
    out = out + "  conflict " + c.text + "\n";
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut rooms: Map<Str, Map<Str, List<Bk>>> = Map::new();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut skipped: List<Str> = [];
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let Some(b) = parse_line(line) else {
      skipped.push((i + 1).to_str());
      continue;
    };
    if seen.get(line).is_some() { continue; }
    seen.insert(line, true);
    let mut days: Map<Str, List<Bk>> = match rooms.get(b.room) {
      Some(d) => d,
      None => Map::new(),
    };
    let mut lst: List<Bk> = match days.get(b.day) {
      Some(l) => l,
      None => [],
    };
    lst.push(b);
    days.insert(b.day, lst);
    rooms.insert(b.room, days);
  }
  let mut out = "";
  for r in rooms.keys() {
    let days: Map<Str, List<Bk>> = rooms.get(r).unwrap_or(Map::new());
    for d in days.keys() {
      let lst: List<Bk> = days.get(d).unwrap_or([]);
      out = out + r + " " + d + "\n" + day_report(lst);
    }
  }
  if skipped.len() == 0 {
    out = out + "skipped: none\n";
  } else {
    out = out + "skipped: " + skipped.join(", ") + "\n";
  }
  Ok(out)
}

struct Fail { path: Str, msg: Str }

fn fail(path: Str, msg: Str) -> Fail {
  Fail { path: path, msg: msg }
}

fn bounds(schema: Json, v: Json) -> Option<Str> {
  let lo = schema.get("minimum").and_then(|j| j.as_int());
  let hi = schema.get("maximum").and_then(|j| j.as_int());
  match v {
    Json::Num(n) => {
      if let Some(l) = lo { if n < l { return Some("less than " + l.to_str()); } }
      if let Some(h) = hi { if n > h { return Some("greater than " + h.to_str()); } }
      None
    },
    Json::Float(f) => {
      if let Some(l) = lo { if f < l.to_float() { return Some("less than " + l.to_str()); } }
      if let Some(h) = hi { if f > h.to_float() { return Some("greater than " + h.to_str()); } }
      None
    },
    _ => None,
  }
}

fn validate(schema: Json, v: Json, path: Str) -> List<Fail> {
  let mut errs: List<Fail> = [];
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  if t == "object" {
    let Some(m) = v.as_map() else {
      errs.push(fail(path, "expected object"));
      return errs;
    };
    let props: Map<Str, Json> = schema.get("properties").and_then(|j| j.as_map()).unwrap_or(Map::new());
    let req: List<Json> = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
    let mut seen: List<Str> = [];
    for r in req {
      if let Some(name) = r.as_str() {
        if !seen.contains(name) {
          seen.push(name);
          if m.get(name).is_none() {
            errs.push(fail(path + "." + name, "missing required field"));
          }
        }
      }
    }
    let additional = schema.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
    for key in m.keys() {
      let Some(val) = m.get(key) else { continue; };
      if let Some(s) = props.get(key) {
        for e in validate(s, val, path + "." + key) { errs.push(e); }
      } else if !additional {
        errs.push(fail(path + "." + key, "unexpected field"));
      }
    }
  } else if t == "array" {
    let Some(items) = v.as_list() else {
      errs.push(fail(path, "expected array"));
      return errs;
    };
    if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
      if items.len() < n {
        errs.push(fail(path, "fewer than " + n.to_str() + " items"));
      }
    }
    if let Some(s) = schema.get("items") {
      for i in 0..items.len() {
        for e in validate(s, items[i], path + "[" + i.to_str() + "]") { errs.push(e); }
      }
    }
  } else if t == "string" {
    let Some(s) = v.as_str() else {
      errs.push(fail(path, "expected string"));
      return errs;
    };
    let n = s.chars().len();
    let mn = schema.get("min_length").and_then(|j| j.as_int());
    let mx = schema.get("max_length").and_then(|j| j.as_int());
    let en = schema.get("enum").and_then(|j| j.as_list());
    let mut done = false;
    if let Some(l) = mn {
      if n < l { errs.push(fail(path, "shorter than " + l.to_str())); done = true; }
    }
    if !done {
      if let Some(h) = mx {
        if n > h { errs.push(fail(path, "longer than " + h.to_str())); done = true; }
      }
    }
    if !done {
      if let Some(list) = en {
        let mut found = false;
        for x in list {
          if let Some(xs) = x.as_str() {
            if xs == s { found = true; }
          }
        }
        if !found { errs.push(fail(path, "not in enum")); }
      }
    }
  } else if t == "integer" {
    match v {
      Json::Num(_) => {
        if let Some(m) = bounds(schema, v) { errs.push(fail(path, m)); }
      },
      _ => errs.push(fail(path, "expected integer")),
    }
  } else if t == "number" {
    match v {
      Json::Num(_) | Json::Float(_) => {
        if let Some(m) = bounds(schema, v) { errs.push(fail(path, m)); }
      },
      _ => errs.push(fail(path, "expected number")),
    }
  } else if t == "boolean" {
    if v.as_bool().is_none() { errs.push(fail(path, "expected boolean")); }
  } else if t == "null" {
    match v {
      Json::Null => {},
      _ => errs.push(fail(path, "expected null")),
    }
  }
  errs
}

fn main(input: Dir) -> Result<Str, Str> {
  let sb = match input.read("schema.json") {
    Ok(b) => b,
    Err(_) => return Err("cannot read schema.json"),
  };
  let schema = match sb.to_str().parse_json() {
    Ok(j) => j,
    Err(e) => return Err("bad schema: " + e),
  };
  let rb = match input.read("records.jsonl") {
    Ok(b) => b,
    Err(_) => return Err("cannot read records.jsonl"),
  };
  let lines = rb.to_str().lines();
  let mut out = "";
  let mut valid = 0;
  let mut total = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    total += 1;
    let label = "line " + (i + 1).to_str() + ": ";
    match line.parse_json() {
      Err(_) => { out = out + label + "invalid JSON\n"; },
      Ok(rec) => {
        let mut errs = validate(schema, rec, "$");
        if errs.len() == 0 {
          valid += 1;
          out = out + label + "ok\n";
        } else {
          errs.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
          for e in errs {
            out = out + label + e.path + ": " + e.msg + "\n";
          }
        }
      },
    }
  }
  out = out + "valid " + valid.to_str() + " of " + total.to_str();
  Ok(out)
}

struct Rec { id: Str, version: Int, body: Str }

fn parse_line(line: Str) -> Option<Rec> {
  let j = line.parse_json().ok()?;
  let id = j.get("id")?.as_str()?;
  let version = j.get("version")?.as_int()?;
  Some(Rec { id: id, version: version, body: line })
}

fn push(api: Http, r: Rec) -> Str {
  for attempt in 0..3 {
    let res = api.send("PUT", "/records/" + r.id, ["content-type: application/json"], r.body.to_bytes(), 0);
    match res {
      Ok(resp) => {
        if resp.status >= 200 && resp.status < 300 {
          return "synced";
        }
        if resp.status >= 400 && resp.status < 500 {
          return "rejected " + resp.status.to_str();
        }
      },
      Err(_) => {},
    }
  }
  "failed"
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let text = input.read("records.jsonl").map_err(|e| "read failed")?.to_str();
  let mut recs: Map<Str, Rec> = Map::new();
  let mut out = "";
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let t = line.trim();
    if t.len() == 0 { continue; }
    match parse_line(t) {
      Some(r) => { recs.insert(r.id, r); },
      None => { out = out + "line " + n.to_str() + " invalid\n"; },
    }
  }
  let mut s = 0;
  let mut u = 0;
  let mut rj = 0;
  let mut f = 0;
  for id in recs.keys() {
    let Some(r) = recs.get(id) else { continue; };
    let key = "v/" + id;
    let stored = state.get(key).map_err(|e| "kv failed")?;
    let last: Option<Int> = match stored {
      Some(b) => b.to_str().parse_int(),
      None => None,
    };
    let need = match last {
      Some(l) => r.version > l,
      None => true,
    };
    if !need {
      u += 1;
      out = out + id + " unchanged\n";
      continue;
    }
    let o = push(api, r);
    if o == "synced" {
      s += 1;
      state.set(key, r.version.to_str().to_bytes()).map_err(|e| "kv failed")?;
    } else if o == "failed" {
      f += 1;
    } else {
      rj += 1;
    }
    out = out + id + " " + o + "\n";
  }
  out = out + "synced " + s.to_str() + " unchanged " + u.to_str() + " rejected " + rj.to_str() + " failed " + f.to_str() + "\n";
  Ok(out)
}

const MAXI: Int = 9223372036854775807;

enum Outcome { Done, Dup, Fail(Str) }

fn num(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn txt(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn padn(n: Int, w: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < w { s = "0" + s; }
  s
}

fn fmt_time(ms: Int) -> Str {
  let mut secs = ms / 1000;
  if ms % 1000 < 0 { secs -= 1; }
  let mut days = secs / 86400;
  let mut rem = secs % 86400;
  if rem < 0 { rem += 86400; days -= 1; }
  let z = days + 719468;
  let era = (if z >= 0 { z } else { z - 146096 }) / 146097;
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let mut y = yoe + era * 400;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  if m <= 2 { y += 1; }
  let hh = rem / 3600;
  let mm = (rem % 3600) / 60;
  let ss = rem % 60;
  padn(y, 4) + "-" + padn(m, 2) + "-" + padn(d, 2) + "T" + padn(hh, 2) + ":" + padn(mm, 2) + ":" + padn(ss, 2) + "Z"
}

fn active_balance(db: Db, name: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", [SqlValue::Text(name)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(num(rows[0][0]))) }
}

fn process(db: Db, now: Int, line: Str) -> Result<Outcome, DbErr> {
  let w = line.split(" ");
  let op = w[0];
  if op == "open" {
    if w.len() != 3 { return Ok(Outcome::Fail("malformed")); }
    let Some(c) = w[2].parse_int() else { return Ok(Outcome::Fail("malformed")); };
    if c < 0 { return Ok(Outcome::Fail("bad amount")); }
    let ex = db.query("SELECT 1 FROM accounts WHERE name = ?", [SqlValue::Text(w[1])])?;
    if ex.len() > 0 { return Ok(Outcome::Fail("account exists")); }
    db.exec("INSERT INTO accounts (name, balance, closed, last_ms) VALUES (?, ?, 0, ?)", [SqlValue::Text(w[1]), SqlValue::Int(c), SqlValue::Int(now)])?;
    return Ok(Outcome::Done);
  }
  if op == "close" {
    if w.len() != 2 { return Ok(Outcome::Fail("malformed")); }
    let Some(b) = active_balance(db, w[1])? else { return Ok(Outcome::Fail("no account " + w[1])); };
    if b != 0 { return Ok(Outcome::Fail("balance not zero")); }
    db.exec("UPDATE accounts SET closed = 1 WHERE name = ?", [SqlValue::Text(w[1])])?;
    return Ok(Outcome::Done);
  }
  if op == "transfer" {
    if w.len() != 5 { return Ok(Outcome::Fail("malformed")); }
    let Some(c) = w[4].parse_int() else { return Ok(Outcome::Fail("malformed")); };
    let id = w[1];
    let from = w[2];
    let to = w[3];
    let prev = db.query("SELECT from_a, to_a, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)])?;
    if prev.len() > 0 {
      let r = prev[0];
      if txt(r[0]) == from && txt(r[1]) == to && num(r[2]) == c { return Ok(Outcome::Dup); }
      return Ok(Outcome::Fail("id reused"));
    }
    if c <= 0 { return Ok(Outcome::Fail("bad amount")); }
    if from == to { return Ok(Outcome::Fail("same account")); }
    let Some(fb) = active_balance(db, from)? else { return Ok(Outcome::Fail("no account " + from)); };
    let Some(tb) = active_balance(db, to)? else { return Ok(Outcome::Fail("no account " + to)); };
    if fb < c { return Ok(Outcome::Fail("insufficient funds")); }
    if tb > MAXI - c { return Ok(Outcome::Fail("overflow")); }
    let stmts = [
      "UPDATE accounts SET balance = balance - ?, last_ms = ? WHERE name = ?",
      "UPDATE accounts SET balance = balance + ?, last_ms = ? WHERE name = ?",
      "INSERT INTO transfers (id, from_a, to_a, cents) VALUES (?, ?, ?, ?)"
    ];
    let params = [
      [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(from)],
      [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(to)],
      [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)]
    ];
    db.transaction(stmts, params)?;
    return Ok(Outcome::Done);
  }
  Ok(Outcome::Fail("malformed"))
}

fn run(db: Db, log: Log, now: Int, text: Str) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, closed INTEGER NOT NULL, last_ms INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, from_a TEXT NOT NULL, to_a TEXT NOT NULL, cents INTEGER NOT NULL)", [])?;
  let stamp = fmt_time(now);
  let mut ok = 0;
  let mut failed = 0;
  let mut dup = 0;
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim() == "" { continue; }
    match process(db, now, line)? {
      Outcome::Done => ok += 1,
      Outcome::Dup => dup += 1,
      Outcome::Fail(m) => {
        failed += 1;
        let _r = log.write(stamp + " line " + n.to_str() + ": " + m);
      },
    }
  }
  let mut out = "ok " + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str() + "\n";
  let rows = db.query("SELECT name, balance, last_ms FROM accounts WHERE closed = 0 ORDER BY name", [])?;
  for r in rows {
    out = out + txt(r[0]) + " " + num(r[1]).to_str() + " last " + fmt_time(num(r[2])) + "\n";
  }
  Ok(out)
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  let text = match input.read("ops.txt") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read ops.txt"),
  };
  let now = clock.now_ms();
  match run(db, log, now, text) {
    Ok(s) => Ok(s),
    Err(_) => Err("database error"),
  }
}

struct Creds { name: Str, password: Str }

fn cont(b: Bytes, i: Int) -> Bool {
  i < b.len() && b[i] >= 128 && b[i] <= 191
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if !cont(b, i + 1) { return false; }
      i += 2;
    } else if c >= 224 && c <= 239 {
      if !cont(b, i + 1) || !cont(b, i + 2) { return false; }
      let d = b[i + 1];
      if c == 224 && d < 160 { return false; }
      if c == 237 && d > 159 { return false; }
      i += 3;
    } else if c >= 240 && c <= 244 {
      if !cont(b, i + 1) || !cont(b, i + 2) || !cont(b, i + 3) { return false; }
      let d = b[i + 1];
      if c == 240 && d < 144 { return false; }
      if c == 244 && d > 143 { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn valid_name(name: Str) -> Bool {
  let n = name.len();
  if n < 3 || n > 20 { return false; }
  for b in name.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 95;
    if !ok { return false; }
  }
  true
}

fn creds(req: Incoming) -> Option<Creds> {
  let body = req.body();
  if !valid_utf8(body) { return None; }
  let Ok(doc) = body.to_str().parse_json() else { return None; };
  let Some(name) = doc.get("name").and_then(|j| j.as_str()) else { return None; };
  let Some(password) = doc.get("password").and_then(|j| j.as_str()) else { return None; };
  Some(Creds { name: name, password: password })
}

fn reply(res: Outgoing, status: Int, body: Str) -> Str {
  let r = res.send(status, ["content-type"], ["application/json"], body.to_bytes());
  ""
}

fn reply_empty(res: Outgoing, status: Int) -> Str {
  let r = res.send(status, [], [], "".to_bytes());
  ""
}

fn err_body(msg: Str) -> Str {
  "{\"error\":\"" + msg + "\"}"
}

fn get_token(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() {
    if names[i] == "authorization" {
      let Some(t) = values[i].strip_prefix("Bearer ") else { return None; };
      if t.len() != 32 { return None; }
      return Some(t);
    }
  }
  None
}

fn int_of(store: Kv, key: Str) -> Result<Int, KvErr> {
  match store.get(key)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

// Returns the session's user name if the token is valid at `now`.
fn session(store: Kv, token: Str, now: Int) -> Result<Option<Str>, KvErr> {
  let Some(v) = store.get("s/" + token)? else { return Ok(None); };
  let parts = v.to_str().split(",");
  if parts.len() != 2 { return Ok(None); }
  let expiry = parts[1].parse_int().unwrap_or(0);
  if now < expiry {
    Ok(Some(parts[0]))
  } else {
    store.delete("s/" + token)?;
    Ok(None)
  }
}

fn create_user(req: Incoming, res: Outgoing, store: Kv) -> Result<Str, KvErr> {
  let Some(c) = creds(req) else { return Ok(reply(res, 400, err_body("invalid"))); };
  if !valid_name(c.name) || c.password.len() < 8 {
    return Ok(reply(res, 400, err_body("invalid")));
  }
  let hash = (c.name + ":" + c.password).sha256().to_hex();
  let made = store.swap("u/" + c.name, None, Some(hash.to_bytes()))?;
  if !made {
    return Ok(reply(res, 409, err_body("name taken")));
  }
  Ok(reply(res, 201, "{\"name\":\"" + c.name + "\"}"))
}

fn login(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, KvErr> {
  let bad = err_body("bad credentials");
  let Some(c) = creds(req) else { return Ok(reply(res, 401, bad)); };
  if !valid_name(c.name) { return Ok(reply(res, 401, bad)); }
  let Some(stored) = store.get("u/" + c.name)? else { return Ok(reply(res, 401, bad)); };
  let now = clock.now_ms();
  let until = int_of(store, "l/" + c.name)?;
  if now < until {
    return Ok(reply(res, 429, err_body("locked")));
  }
  let hash = (c.name + ":" + c.password).sha256().to_hex();
  if !stored.to_str().ct_eq(hash) {
    let n = store.add("f/" + c.name, 1)?;
    if n >= 3 {
      store.set("l/" + c.name, (now + 900000).to_str().to_bytes())?;
      store.delete("f/" + c.name)?;
    }
    return Ok(reply(res, 401, bad));
  }
  store.delete("f/" + c.name)?;
  store.add("n/" + c.name, 1)?;
  let token = rng.bytes(16).to_hex();
  let expiry = now + 1800000;
  store.set("s/" + token, (c.name + "," + expiry.to_str()).to_bytes())?;
  Ok(reply(res, 200, "{\"token\":\"" + token + "\",\"expires_in\":1800}"))
}

fn me(req: Incoming, res: Outgoing, store: Kv, clock: Clock) -> Result<Str, KvErr> {
  let unauth = err_body("unauthorized");
  let Some(token) = get_token(req) else { return Ok(reply(res, 401, unauth)); };
  let now = clock.now_ms();
  let Some(name) = session(store, token, now)? else { return Ok(reply(res, 401, unauth)); };
  store.set("s/" + token, (name + "," + (now + 1800000).to_str()).to_bytes())?;
  let logins = int_of(store, "n/" + name)?;
  Ok(reply(res, 200, "{\"name\":\"" + name + "\",\"logins\":" + logins.to_str() + "}"))
}

fn logout(req: Incoming, res: Outgoing, store: Kv, clock: Clock) -> Result<Str, KvErr> {
  let unauth = err_body("unauthorized");
  let Some(token) = get_token(req) else { return Ok(reply(res, 401, unauth)); };
  let now = clock.now_ms();
  let Some(name) = session(store, token, now)? else { return Ok(reply(res, 401, unauth)); };
  store.delete("s/" + token)?;
  Ok(reply_empty(res, 204))
}

fn handle(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, KvErr> {
  let method = req.method();
  let path = req.target().split("?")[0];
  if path == "/users" && method == "POST" {
    return create_user(req, res, store);
  }
  if path == "/login" && method == "POST" {
    return login(req, res, store, clock, rng);
  }
  if path == "/me" && method == "GET" {
    return me(req, res, store, clock);
  }
  if path == "/logout" && method == "POST" {
    return logout(req, res, store, clock);
  }
  Ok(reply(res, 404, err_body("not found")))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
  match handle(req, res, store, clock, rng) {
    Ok(s) => s,
    Err(e) => reply(res, 500, err_body("internal")),
  }
}

struct Resp { status: Int, body: Str }

const COLS: Str = "n, account, cents, currency, status, refunded";

fn sint(v: SqlValue) -> Int {
  match v { SqlValue::Int(i) => i, _ => 0 }
}

fn stext(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn err(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn nf() -> Resp { err(404, "not found") }

fn pay_json(row: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + sint(row[0]).to_str()));
  m.insert("account", Json::Str(stext(row[1])));
  m.insert("cents", Json::Num(sint(row[2])));
  m.insert("currency", Json::Str(stext(row[3])));
  m.insert("status", Json::Str(stext(row[4])));
  m.insert("refunded", Json::Num(sint(row[5])));
  Json::Obj(m)
}

fn pay_resp(status: Int, row: List<SqlValue>) -> Resp {
  Resp { status: status, body: pay_json(row).to_json() }
}

fn header(req: Incoming, name: Str) -> Option<Str> {
  let ns = req.header_names();
  let vs = req.header_values();
  for i in 0..ns.len() {
    if ns[i] == name {
      if vs[i].len() == 0 { return None; }
      return Some(vs[i]);
    }
  }
  None
}

fn parse_id(s: Str) -> Option<Int> {
  let d = s.strip_prefix("pay_")?;
  let n = d.parse_int()?;
  if n > 0 && n.to_str() == d { Some(n) } else { None }
}

fn hexval(c: Int) -> Option<Int> {
  if c >= 48 && c <= 57 { return Some(c - 48); }
  if c >= 97 && c <= 102 { return Some(c - 87); }
  if c >= 65 && c <= 70 { return Some(c - 55); }
  None
}

fn decode(s: Str) -> Str {
  let b = s.to_bytes();
  let mut out = "".to_bytes();
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    if c == 43 {
      out.push(32);
      i += 1;
    } else if c == 37 && i + 2 < b.len() + 0 + 0 {
      let h = hexval(b[i + 1]);
      let l = hexval(b[i + 2]);
      match h {
        Some(hv) => match l {
          Some(lv) => { out.push(hv * 16 + lv); i += 3; },
          None => { out.push(c); i += 1; },
        },
        None => { out.push(c); i += 1; },
      }
    } else {
      out.push(c);
      i += 1;
    }
  }
  out.to_str()
}

fn fetch(db: Db, id: Int) -> Result<Option<List<SqlValue>>, DbErr> {
  let rows = db.query("SELECT " + COLS + " FROM payments WHERE n = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(rows[0])) }
}

fn replay(db: Db, key: Str, method: Str, path: Str, canon: Str) -> Result<Option<Resp>, DbErr> {
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE k = ?", [SqlValue::Text(key)])?;
  if rows.len() == 0 { return Ok(None); }
  let row = rows[0];
  let st = sint(row[3]);
  if st == 0 { return Ok(Some(err(409, "key reused"))); }
  if stext(row[0]) == method && stext(row[1]) == path && stext(row[2]) == canon {
    Ok(Some(Resp { status: st, body: stext(row[4]) }))
  } else {
    Ok(Some(err(409, "key reused")))
  }
}

fn canon_of(raw: Str) -> Str {
  match raw.parse_json() {
    Ok(j) => j.to_json(),
    Err(_) => "!" + raw,
  }
}

// Claims the key. Returns Some(response) if the request must stop here.
fn claim(db: Db, key: Str, method: Str, path: Str, canon: Str) -> Result<Option<Resp>, DbErr> {
  let r = db.exec("INSERT INTO idem (k, method, path, body, status, resp) VALUES (?, ?, ?, ?, 0, '')",
    [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon)]);
  match r {
    Ok(_) => Ok(None),
    Err(DbErr::Constraint(_)) => {
      match replay(db, key, method, path, canon)? {
        Some(x) => Ok(Some(x)),
        None => Ok(Some(err(409, "key reused"))),
      }
    },
    Err(e) => Err(e),
  }
}

fn finish(db: Db, key: Str, resp: Resp) -> Result<Resp, DbErr> {
  if resp.status / 100 == 2 {
    db.exec("UPDATE idem SET status = ?, resp = ? WHERE k = ?",
      [SqlValue::Int(resp.status), SqlValue::Text(resp.body), SqlValue::Text(key)])?;
  } else {
    db.exec("DELETE FROM idem WHERE k = ?", [SqlValue::Text(key)])?;
  }
  Ok(resp)
}

fn create(db: Db, key: Str, path: Str, raw: Str) -> Result<Resp, DbErr> {
  let canon = canon_of(raw);
  if let Some(r) = replay(db, key, "POST", path, canon)? { return Ok(r); }
  let bad = err(422, "invalid payment");
  let obj = match raw.parse_json() {
    Ok(Json::Obj(m)) => m,
    _ => return Ok(bad),
  };
  if obj.len() != 3 { return Ok(bad); }
  let account = obj.get("account").and_then(|j| j.as_str()).unwrap_or("");
  let currency = obj.get("currency").and_then(|j| j.as_str()).unwrap_or("");
  let cents = obj.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
  if account.len() == 0 || cents <= 0 { return Ok(bad); }
  if currency != "EUR" && currency != "USD" { return Ok(bad); }
  if let Some(r) = claim(db, key, "POST", path, canon)? { return Ok(r); }
  db.exec("INSERT INTO payments (account, cents, currency, status, refunded, ikey) VALUES (?, ?, ?, 'pending', 0, ?)",
    [SqlValue::Text(account), SqlValue::Int(cents), SqlValue::Text(currency), SqlValue::Text(key)])?;
  let rows = db.query("SELECT " + COLS + " FROM payments WHERE ikey = ?", [SqlValue::Text(key)])?;
  let resp = if rows.len() == 0 { err(500, "internal") } else { pay_resp(201, rows[0]) };
  finish(db, key, resp)
}

fn refund(db: Db, key: Str, path: Str, id: Int, raw: Str) -> Result<Resp, DbErr> {
  let canon = canon_of(raw);
  if let Some(r) = replay(db, key, "POST", path, canon)? { return Ok(r); }
  let obj = match raw.parse_json() {
    Ok(Json::Obj(m)) => m,
    _ => return Ok(err(422, "invalid refund")),
  };
  let n = obj.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
  if n <= 0 { return Ok(err(422, "invalid refund")); }
  if let Some(r) = claim(db, key, "POST", path, canon)? { return Ok(r); }
  let changed = db.exec("UPDATE payments SET status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END, refunded = refunded + ? WHERE n = ? AND status = 'captured' AND refunded + ? <= cents",
    [SqlValue::Int(n), SqlValue::Int(n), SqlValue::Int(id), SqlValue::Int(n)])?;
  let cur = fetch(db, id)?;
  let resp = match cur {
    None => nf(),
    Some(row) => {
      if changed == 1 {
        pay_resp(200, row)
      } else if stext(row[4]) != "captured" {
        err(409, "invalid transition")
      } else {
        err(409, "exceeds captured")
      }
    },
  };
  finish(db, id_key(key), resp)
}

fn id_key(k: Str) -> Str { k }

fn transition(db: Db, id: Int, from: Str, to: Str) -> Result<Resp, DbErr> {
  let changed = db.exec("UPDATE payments SET status = ? WHERE n = ? AND status = ?",
    [SqlValue::Text(to), SqlValue::Int(id), SqlValue::Text(from)])?;
  let cur = fetch(db, id)?;
  match cur {
    None => Ok(nf()),
    Some(row) => {
      if changed == 1 {
        Ok(pay_resp(200, row))
      } else if to == "captured" && stext(row[4]) == "captured" {
        Ok(pay_resp(200, row))
      } else {
        Ok(err(409, "invalid transition"))
      }
    },
  }
}

fn list(db: Db, query: Str) -> Result<Resp, DbErr> {
  let mut account: Option<Str> = None;
  for pair in query.split("&") {
    if let Some(v) = pair.strip_prefix("account=") { account = Some(decode(v)); }
  }
  let rows = match account {
    Some(a) => db.query("SELECT " + COLS + " FROM payments WHERE account = ? ORDER BY n", [SqlValue::Text(a)])?,
    None => db.query("SELECT " + COLS + " FROM payments ORDER BY n", [])?,
  };
  let mut out: List<Json> = [];
  for row in rows { out.push(pay_json(row)); }
  Ok(Resp { status: 200, body: Json::Arr(out).to_json() })
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL, ikey TEXT UNIQUE)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  let method = req.method();
  let target = req.target();
  let qi = target.find("?");
  let path = match qi { Some(i) => target.slice(0, i), None => target };
  let query = match qi { Some(i) => target.slice(i + 1, target.len()), None => "" };
  if path == "/payments" {
    if method == "POST" {
      let Some(key) = header(req, "idempotency-key") else {
        return Ok(err(400, "missing idempotency key"));
      };
      return create(db, key, path, req.body().to_str());
    }
    if method == "GET" { return list(db, query); }
    return Ok(nf());
  }
  let Some(rest) = path.strip_prefix("/payments/") else { return Ok(nf()); };
  let parts = rest.split("/");
  let Some(id) = parse_id(parts[0]) else { return Ok(nf()); };
  if parts.len() == 1 {
    if method == "GET" {
      return match fetch(db, id)? {
        Some(row) => Ok(pay_resp(200, row)),
        None => Ok(nf()),
      };
    }
    return Ok(nf());
  }
  if parts.len() == 2 && method == "POST" {
    if parts[1] == "capture" { return transition(db, id, "pending", "captured"); }
    if parts[1] == "cancel" { return transition(db, id, "pending", "canceled"); }
    if parts[1] == "refund" {
      let Some(key) = header(req, "idempotency-key") else {
        return Ok(err(400, "missing idempotency key"));
      };
      return refund(db, key, path, id, req.body().to_str());
    }
  }
  Ok(nf())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => err(500, "internal error"),
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok("")
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn num(b: Bytes, s: Int, e: Int) -> Int {
  let mut n = 0;
  let mut i = s;
  while i < e {
    n = n * 10 + b[i] - 48;
    i += 1;
  }
  n
}

fn parse_time(s: Str) -> Option<Int> {
  if s.len() != 20 { return None; }
  let b = s.to_bytes();
  for i in 0..20 {
    let c = b[i];
    let ok = if i == 4 || i == 7 { c == 45 }
      else if i == 10 { c == 84 }
      else if i == 13 || i == 16 { c == 58 }
      else if i == 19 { c == 90 }
      else { c >= 48 && c <= 57 };
    if !ok { return None; }
  }
  let y = num(b, 0, 4);
  let mo = num(b, 5, 7);
  let d = num(b, 8, 10);
  let h = num(b, 11, 13);
  let mi = num(b, 14, 16);
  let se = num(b, 17, 19);
  if mo < 1 || mo > 12 { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
  let dim = if mo == 2 { if leap { 29 } else { 28 } }
    else if mo == 4 || mo == 6 || mo == 9 || mo == 11 { 30 }
    else { 31 };
  if d < 1 || d > dim { return None; }
  let mut y2 = y + 400;
  if mo <= 2 { y2 = y2 - 1; }
  let era = y2 / 400;
  let yoe = y2 - era * 400;
  let mp = (mo + 9) % 12;
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  let days = era * 146097 + doe;
  Some(days * 86400 + h * 3600 + mi * 60 + se)
}

fn hms(d: Int) -> Str {
  pad2(d / 3600) + ":" + pad2((d % 3600) / 60) + ":" + pad2(d % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut times: Map<Str, List<Int>> = Map::new();
  let mut pagecount: Map<Str, Int> = Map::new();
  let mut userpages: Map<Str, Int> = Map::new();
  let mut upseen: HashMap<Str, Bool> = HashMap::new();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut malformed = 0;
  let mut dups = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    if parts.len() != 3 { malformed += 1; continue; }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    let u = parts[1];
    let p = parts[2];
    let mut l = times.get(u).unwrap_or([]);
    l.push(t);
    times.insert(u, l);
    pagecount.insert(p, pagecount.get(p).unwrap_or(0) + 1);
    let key = u + " " + p;
    if upseen.get(key).is_none() {
      upseen.insert(key, true);
      userpages.insert(u, userpages.get(u).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  let mut durations: List<Int> = [];
  for u in times.keys() {
    let mut l = times.get(u).unwrap_or([]);
    l.sort();
    let mut start = l[0];
    let mut prev = l[0];
    let mut sessions = 0;
    let mut longest = 0;
    for t in l {
      if t - prev > 1800 {
        let d = prev - start;
        durations.push(d);
        sessions += 1;
        if d > longest { longest = d; }
        start = t;
      }
      prev = t;
    }
    let d = prev - start;
    durations.push(d);
    sessions += 1;
    if d > longest { longest = d; }
    out.push(u + " sessions " + sessions.to_str() + " events " + l.len().to_str()
      + " longest " + hms(longest) + " pages " + userpages.get(u).unwrap_or(0).to_str());
  }
  if durations.len() > 0 {
    durations.sort();
    let med = durations[(durations.len() - 1) / 2];
    out.push("median " + med.to_str());
    let counts = pagecount;
    let mut pages = counts.keys();
    pages.sort_by(|a, b| {
      let ca = counts.get(a).unwrap_or(0);
      let cb = counts.get(b).unwrap_or(0);
      ca > cb || (ca == cb && a < b)
    });
    let mut tops: List<Str> = [];
    let mut i = 0;
    while i < 3 && i < pages.len() {
      tops.push(pages[i] + " (" + counts.get(pages[i]).unwrap_or(0).to_str() + ")");
      i += 1;
    }
    out.push("top: " + tops.join(", "));
  }
  out.push("malformed " + malformed.to_str() + " duplicates " + dups.to_str());
  Ok(out.join("\n") + "\n")
}

struct Rec { fields: List<Str>, bad: Bool }

fn parse(b: Bytes) -> List<Rec> {
  let n = b.len();
  let mut recs: List<Rec> = [];
  let mut i = 0;
  while i < n {
    if b[i] == 10 { i += 1; continue; }
    if b[i] == 13 && i + 1 < n && b[i + 1] == 10 { i += 2; continue; }
    let mut fields: List<Str> = [];
    let mut cur: Bytes = "".to_bytes();
    let mut mode = 0;
    let mut bad = false;
    let mut done = false;
    while !done {
      if i >= n {
        if mode == 2 { bad = true; }
        done = true;
        continue;
      }
      let c = b[i];
      if mode == 2 {
        if c == 34 {
          if i + 1 < n && b[i + 1] == 34 {
            cur.push(34);
            i += 2;
          } else {
            mode = 3;
            i += 1;
          }
        } else {
          cur.push(c);
          i += 1;
        }
      } else {
        let crlf = c == 13 && i + 1 < n && b[i + 1] == 10;
        if c == 10 || crlf {
          if crlf { i += 2; } else { i += 1; }
          done = true;
        } else if c == 44 {
          fields.push(cur.to_str());
          cur = "".to_bytes();
          mode = 0;
          i += 1;
        } else if mode == 0 {
          if c == 34 {
            mode = 2;
          } else {
            cur.push(c);
            mode = 1;
          }
          i += 1;
        } else if mode == 1 {
          if c == 34 { bad = true; }
          cur.push(c);
          i += 1;
        } else {
          bad = true;
          i += 1;
        }
      }
    }
    fields.push(cur.to_str());
    recs.push(Rec { fields: fields, bad: bad });
  }
  recs
}

fn all_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for c in s.to_bytes() {
    if c < 48 || c > 57 { return false; }
  }
  true
}

fn qty_of(s: Str) -> Option<Int> {
  if s.starts_with("-") {
    let rest = s.slice(1, s.len());
    if !all_digits(rest) { return None; }
    s.parse_int()
  } else {
    if !all_digits(s) { return None; }
    s.parse_int()
  }
}

fn cents_of(s: Str) -> Option<Int> {
  let parts = s.split(".");
  if parts.len() == 1 {
    if !all_digits(parts[0]) { return None; }
    let w = parts[0].parse_int()?;
    if w > 90000000000000000 { return None; }
    Some(w * 100)
  } else if parts.len() == 2 {
    if !all_digits(parts[0]) || !all_digits(parts[1]) { return None; }
    let f = parts[1];
    if f.len() > 2 { return None; }
    let w = parts[0].parse_int()?;
    if w > 90000000000000000 { return None; }
    let mut fr = f.parse_int()?;
    if f.len() == 1 { fr = fr * 10; }
    Some(w * 100 + fr)
  } else {
    None
  }
}

fn money(c: Int) -> Str {
  let mut a = c;
  let mut sign = "";
  if c < 0 { a = -c; sign = "-"; }
  let whole = a / 100;
  let fr = a % 100;
  let mut fs = fr.to_str();
  if fr < 10 { fs = "0" + fs; }
  sign + whole.to_str() + "." + fs
}

fn q(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let data = input.read("sales.csv")?;
  let recs = parse(data);
  let mut clean = "region,product,qty,price,note\n";
  let mut rev: Map<Str, Int> = Map::new();
  let mut qtys: Map<Str, Int> = Map::new();
  let mut prods: Map<Str, Map<Str, Int>> = Map::new();
  let mut badl: List<Str> = [];
  let mut total = 0;
  if recs.len() > 1 {
    for idx in 1..recs.len() {
      total += 1;
      let r = recs[idx];
      let mut ok = false;
      if !r.bad && r.fields.len() == 5 && r.fields[0].len() > 0 && r.fields[1].len() > 0 {
        let qo = qty_of(r.fields[2]);
        let po = cents_of(r.fields[3]);
        if let Some(qty) = qo {
          if let Some(cents) = po {
            ok = true;
            let region = r.fields[0];
            let product = r.fields[1];
            let rv = qty * cents;
            rev.insert(region, rev.get(region).unwrap_or(0) + rv);
            qtys.insert(region, qtys.get(region).unwrap_or(0) + qty);
            let mut pm: Map<Str, Int> = prods.get(region).unwrap_or(Map::new());
            pm.insert(product, pm.get(product).unwrap_or(0) + rv);
            prods.insert(region, pm);
            clean = clean + q(region) + "," + q(product) + "," + q(r.fields[2]) + "," + money(cents) + "," + q(r.fields[4]) + "\n";
          }
        }
      }
      if !ok { badl.push(idx.to_str()); }
    }
  }
  out.create("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for region in rev.keys() {
    let pm: Map<Str, Int> = prods.get(region).unwrap_or(Map::new());
    let mut best = "";
    let mut bestv = 0;
    let mut first = true;
    for p in pm.keys() {
      let v = pm.get(p).unwrap_or(0);
      if first || v > bestv {
        best = p;
        bestv = v;
        first = false;
      }
    }
    lines.push(region + " revenue " + money(rev.get(region).unwrap_or(0)) + " items " + qtys.get(region).unwrap_or(0).to_str() + " top " + best);
  }
  let mut last = "records " + total.to_str() + " bad " + badl.len().to_str();
  if badl.len() > 0 { last = last + ": " + badl.join(", "); }
  lines.push(last);
  Ok(lines.join("\n"))
}

fn ierr(e: IoErr) -> Str { "io error" }
fn kerr(e: KvErr) -> Str { "kv error" }

fn word_set(b: Bytes) -> Map<Str, Bool> {
  let mut set: Map<Str, Bool> = Map::new();
  let mut cur: Bytes = "".to_bytes();
  for c in b {
    let alnum = (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122);
    if c < 128 && !alnum {
      if cur.len() > 0 {
        set.insert(cur.to_str().to_lowercase(), true);
        cur = "".to_bytes();
      }
    } else {
      cur.push(c);
    }
  }
  if cur.len() > 0 {
    set.insert(cur.to_str().to_lowercase(), true);
  }
  set
}

fn walk(d: Dir, dir: Str, out: List<Str>) -> Result<List<Str>, Str> {
  let names = d.list(dir).map_err(ierr)?;
  let mut res: List<Str> = out;
  for n in names {
    if n.ends_with("/") {
      let name = n.slice(0, n.len() - 1);
      let sub = if dir == "" { name } else { dir + "/" + name };
      res = walk(d, sub, res)?;
    } else {
      let full = if dir == "" { n } else { dir + "/" + n };
      res.push(full);
    }
  }
  Ok(res)
}

fn scan_all(index: Kv, prefix: Str) -> Result<List<KvEntry>, Str> {
  let mut all: List<KvEntry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = index.scan(prefix, after, 1000).map_err(kerr)?;
    for e in page { all.push(e); }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(all)
}

fn index_file(index: Kv, p: Str, content: Bytes, h: Bytes) -> Result<(), Str> {
  let ws = word_set(content).keys();
  for w in ws {
    index.set("w/" + w + "/" + p, "".to_bytes()).map_err(kerr)?;
  }
  index.set("t/" + p, ws.join("\n").to_bytes()).map_err(kerr)?;
  index.set("f/" + p, h).map_err(kerr)?;
  Ok(())
}

fn unindex(index: Kv, p: Str) -> Result<(), Str> {
  let t = index.get("t/" + p).map_err(kerr)?;
  if let Some(b) = t {
    for w in b.to_str().split("\n") {
      if w.len() > 0 {
        index.delete("w/" + w + "/" + p).map_err(kerr)?;
      }
    }
  }
  Ok(())
}

fn paths_for(index: Kv, word: Str) -> Result<List<Str>, Str> {
  let prefix = "w/" + word + "/";
  let entries = scan_all(index, prefix)?;
  let mut out: List<Str> = [];
  for e in entries {
    out.push(e.key.slice(prefix.len(), e.key.len()));
  }
  Ok(out)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let mut paths = walk(docs, "", [])?;
  paths.sort();
  let mut old: Map<Str, Bytes> = Map::new();
  for e in scan_all(index, "f/")? {
    old.insert(e.key.slice(2, e.key.len()), e.value);
  }
  let mut cur: Map<Str, Bool> = Map::new();
  for p in paths { cur.insert(p, true); }

  let mut events: Map<Str, Str> = Map::new();
  let mut unchanged = 0;
  for p in paths {
    let content = docs.read(p).map_err(ierr)?;
    let h = content.sha256();
    match old.get(p) {
      None => {
        events.insert(p, "added");
        index_file(index, p, content, h)?;
      }
      Some(oh) => {
        if oh != h {
          events.insert(p, "changed");
          unindex(index, p)?;
          index_file(index, p, content, h)?;
        } else {
          unchanged += 1;
        }
      }
    }
  }
  for p in old.keys() {
    if cur.get(p).is_none() {
      events.insert(p, "removed");
      unindex(index, p)?;
      index.delete("t/" + p).map_err(kerr)?;
      index.delete("f/" + p).map_err(kerr)?;
    }
  }

  let mut out = "";
  for k in events.keys() {
    out = out + events.get(k).unwrap_or("") + " " + k + "\n";
  }
  out = out + "unchanged " + unchanged.to_str() + "\n";

  let qtext = queries.read("queries.txt").map_err(ierr)?.to_str();
  for line in qtext.lines() {
    if line.trim().len() == 0 { continue; }
    let ws = word_set(line.to_bytes()).keys();
    let mut res: List<Str> = [];
    if ws.len() == 0 {
      res = paths;
    } else {
      res = paths_for(index, ws[0])?;
      for i in 1..ws.len() {
        let mut m: Map<Str, Bool> = Map::new();
        for x in paths_for(index, ws[i])? { m.insert(x, true); }
        res = res.filter(|x| m.get(x).is_some());
      }
    }
    let shown = if res.len() == 0 { "none" } else { res.join(", ") };
    out = out + line + ": " + shown + "\n";
  }
  Ok(out)
}

struct Change { del: Bool, sku: Str, name: Str, qty: Int, version: Int }

fn parse_change(c: Json) -> Option<Change> {
  let op = c.get("op")?.as_str()?;
  let sku = c.get("sku")?.as_str()?;
  let version = c.get("version")?.as_int()?;
  if op == "delete" {
    return Some(Change { del: true, sku: sku, name: "", qty: 0, version: version });
  }
  if op == "upsert" {
    let name = c.get("name")?.as_str()?;
    let qty = c.get("qty")?.as_int()?;
    return Some(Change { del: false, sku: sku, name: name, qty: qty, version: version });
  }
  None
}

fn parse_page(text: Str) -> Option<Json> {
  let Ok(j) = text.parse_json() else { return None; };
  let Some(ch) = j.get("changes") else { return None; };
  let Some(_l) = ch.as_list() else { return None; };
  Some(j)
}

fn get_version(db: Db, local: Map<Str, Int>, sku: Str) -> Result<Option<Int>, DbErr> {
  if let Some(v) = local.get(sku) { return Ok(Some(v)); }
  let rows = db.query("SELECT version FROM items WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn txt(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;
  let crow = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  let mut cursor = "0";
  if crow.len() > 0 {
    cursor = txt(crow[0][0]);
  }
  let upsert_sql = "INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, ?, ?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = excluded.deleted";
  let cursor_sql = "INSERT INTO meta (k, v) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v";
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "complete";
  loop {
    let r = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0);
    let Ok(resp) = r else {
      status = "stopped at " + cursor + " (no response)";
      break;
    };
    if resp.status != 200 {
      status = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    let Some(doc) = parse_page(resp.body.to_str()) else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let changes = doc.get("changes").and_then(|x| x.as_list()).unwrap_or([]);
    let next = doc.get("next").and_then(|x| x.as_str());
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut local: Map<Str, Int> = Map::new();
    let mut pa = 0;
    let mut ps = 0;
    let mut pi = 0;
    for c in changes {
      let Some(ch) = parse_change(c) else {
        pi += 1;
        continue;
      };
      let cur = get_version(db, local, ch.sku)?;
      let mut is_stale = false;
      if let Some(v) = cur {
        if ch.version <= v { is_stale = true; }
      }
      if is_stale {
        ps += 1;
        continue;
      }
      pa += 1;
      local.insert(ch.sku, ch.version);
      let mut d = 0;
      if ch.del { d = 1; }
      stmts.push(upsert_sql);
      params.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty), SqlValue::Int(ch.version), SqlValue::Int(d)]);
    }
    let mut newc = cursor;
    if let Some(n) = next { newc = n; }
    stmts.push(cursor_sql);
    params.push([SqlValue::Text(newc)]);
    db.transaction(stmts, params)?;
    pages += 1;
    applied += pa;
    stale += ps;
    invalid += pi;
    if next.is_none() {
      break;
    }
    cursor = newc;
  }
  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n" + status + "\n";
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for row in rows {
    out = out + txt(row[0]) + " " + int(row[1]).to_str() + " " + txt(row[2]) + "\n";
  }
  Ok(out)
}

struct Job { id: Str, prio: Int, due: Int, att: Int, st: Str }

fn parse_line(line: Str, now: Int) -> Option<Job> {
  let j = line.parse_json().ok()?;
  let id = j.get("id").and_then(|x| x.as_str())?;
  let prio = j.get("priority").and_then(|x| x.as_int())?;
  Some(Job { id: id, prio: prio, due: now, att: 0, st: "pending" })
}

fn load_job(kv: Kv, id: Str) -> Result<Option<Job>, Str> {
  let r = kv.get("job/" + id);
  match r {
    Err(_) => Err("kv error"),
    Ok(None) => Ok(None),
    Ok(Some(b)) => {
      let j = match b.to_str().parse_json() {
        Ok(j) => j,
        Err(e) => return Err(e),
      };
      let prio = j.get("p").and_then(|x| x.as_int()).unwrap_or(0);
      let due = j.get("due").and_then(|x| x.as_int()).unwrap_or(0);
      let att = j.get("att").and_then(|x| x.as_int()).unwrap_or(0);
      let st = j.get("st").and_then(|x| x.as_str()).unwrap_or("pending");
