fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let mut out: List<Str> = [];

  let text = match input.read("enqueue.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let lines = text.lines();
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let n = i + 1;
    let Some(job) = parse_line(line, now) else {
      out.push("invalid line " + n.to_str());
      continue;
    };
    let existing = load_job(queue, job.id)?;
    if existing.is_some() {
      out.push("duplicate ID");
      continue;
    }
    save(queue, job)?;
  }

  let stext = match input.read("script.json") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let script = match stext.parse_json() {
    Ok(j) => j,
    Err(_) => Json::Obj(Map::new()),
  };

  let ids = all_ids(queue)?;
  let mut due: List<Job> = [];
  for id in ids {
    let Some(j) = load_job(queue, id)? else { continue; };
    if j.st == "pending" && j.due <= now {
      due.push(j);
    }
  }
  due.sort_by(|a: Job, b: Job| {
    if a.prio != b.prio { a.prio > b.prio }
    else if a.due != b.due { a.due < b.due }
    else { a.id < b.id }
  });

  let cnt = 5.min(due.len());
  for i in 0..cnt {
    let j = due[i];
    let outs = script.get(j.id).and_then(|x| x.as_list()).unwrap_or([]);
    let mut ok = true;
    if outs.len() > 0 {
      let idx = j.att.min(outs.len() - 1);
      ok = outs[idx].as_str().unwrap_or("ok") != "fail";
    }
    if ok {
      save(queue, Job { st: "done", att: j.att + 1, ..j })?;
      out.push("done " + j.id);
    } else {
      let natt = j.att + 1;
      if natt >= 4 {
        save(queue, Job { st: "dead", att: natt, ..j })?;
        out.push("dead " + j.id);
      } else {
        let mut secs = 60;
        if natt == 2 { secs = 120; }
        if natt == 3 { secs = 240; }
        save(queue, Job { due: now + secs * 1000, att: natt, ..j })?;
        out.push("retry " + j.id + " in " + secs.to_str());
      }
    }
  }

  let ids2 = all_ids(queue)?;
  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for id in ids2 {
    let Some(j) = load_job(queue, id)? else { continue; };
    if j.st == "done" { d += 1; }
    else if j.st == "dead" { x += 1; }
    else { p += 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());
  Ok(out.join("\n"))
}

