struct Tok { kind: Int, text: Str }
struct Node { kind: Int, text: Str, kids: List<Node> }
struct PR { node: Node, pos: Int }
struct Stmt { is_let: Bool, name: Str, expr: Node }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_start(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
fn is_op(t: Tok, s: Str) -> Bool { t.kind == 2 && t.text == s }

fn tokenize(s: Str) -> Option<List<Tok>> {
  let b = s.to_bytes();
  let n = b.len();
  let mut toks: List<Tok> = [];
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c == 32 || c == 9 || c == 13 {
      i += 1;
    } else if is_digit(c) {
      let mut j = i;
      while j < n && is_digit(b[j]) { j += 1; }
      toks.push(Tok { kind: 0, text: s.slice(i, j) });
      i = j;
    } else if is_start(c) {
      let mut j = i;
      while j < n && (is_start(b[j]) || is_digit(b[j])) { j += 1; }
      toks.push(Tok { kind: 1, text: s.slice(i, j) });
      i = j;
    } else if c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94 || c == 40 || c == 41 || c == 44 || c == 61 {
      toks.push(Tok { kind: 2, text: s.slice(i, i + 1) });
      i += 1;
    } else {
      return None;
    }
  }
  toks.push(Tok { kind: 3, text: "" });
  Some(toks)
}

fn parse_atom(t: List<Tok>, p: Int) -> Option<PR> {
  let tk = t[p];
  if tk.kind == 0 {
    return Some(PR { node: Node { kind: 0, text: tk.text, kids: [] }, pos: p + 1 });
  }
  if tk.kind == 1 {
    if is_op(t[p + 1], "(") {
      let first = parse_expr(t, p + 2)?;
      let mut args: List<Node> = [first.node];
      let mut pos = first.pos;
      while is_op(t[pos], ",") {
        let r = parse_expr(t, pos + 1)?;
        args.push(r.node);
        pos = r.pos;
      }
      if !is_op(t[pos], ")") { return None; }
      return Some(PR { node: Node { kind: 2, text: tk.text, kids: args }, pos: pos + 1 });
    }
    return Some(PR { node: Node { kind: 1, text: tk.text, kids: [] }, pos: p + 1 });
  }
  if is_op(tk, "(") {
    let r = parse_expr(t, p + 1)?;
    if !is_op(t[r.pos], ")") { return None; }
    return Some(PR { node: r.node, pos: r.pos + 1 });
  }
  None
}

fn parse_power(t: List<Tok>, p: Int) -> Option<PR> {
  let a = parse_atom(t, p)?;
  if is_op(t[a.pos], "^") {
    let e = parse_factor(t, a.pos + 1)?;
    return Some(PR { node: Node { kind: 3, text: "^", kids: [a.node, e.node] }, pos: e.pos });
  }
  Some(a)
}

fn parse_factor(t: List<Tok>, p: Int) -> Option<PR> {
  if is_op(t[p], "-") {
    let r = parse_factor(t, p + 1)?;
    return Some(PR { node: Node { kind: 4, text: "-", kids: [r.node] }, pos: r.pos });
  }
  parse_power(t, p)
}

fn parse_term(t: List<Tok>, p: Int) -> Option<PR> {
  let first = parse_factor(t, p)?;
  let mut node = first.node;
  let mut pos = first.pos;
  loop {
    let tk = t[pos];
    if is_op(tk, "*") || is_op(tk, "/") || is_op(tk, "%") {
      let r = parse_factor(t, pos + 1)?;
      node = Node { kind: 3, text: tk.text, kids: [node, r.node] };
      pos = r.pos;
    } else {
      break;
    }
  }
  Some(PR { node: node, pos: pos })
}

fn parse_expr(t: List<Tok>, p: Int) -> Option<PR> {
  let first = parse_term(t, p)?;
  let mut node = first.node;
  let mut pos = first.pos;
  loop {
    let tk = t[pos];
    if is_op(tk, "+") || is_op(tk, "-") {
      let r = parse_term(t, pos + 1)?;
      node = Node { kind: 3, text: tk.text, kids: [node, r.node] };
      pos = r.pos;
    } else {
      break;
    }
  }
  Some(PR { node: node, pos: pos })
}

fn parse_line(t: List<Tok>) -> Option<Stmt> {
  let dummy = Node { kind: 0, text: "0", kids: [] };
  if t[0].kind == 1 && t[0].text == "let" {
    if t[1].kind != 1 { return None; }
    if !is_op(t[2], "=") { return None; }
    let r = parse_expr(t, 3)?;
    if t[r.pos].kind != 3 { return None; }
    return Some(Stmt { is_let: true, name: t[1].text, expr: r.node });
  }
  let r = parse_expr(t, 0)?;
  if t[r.pos].kind != 3 { return None; }
  Some(Stmt { is_let: false, name: "", expr: r.node })
}

fn max_int() -> Int { 9223372036854775807 }
fn min_int() -> Int { -9223372036854775807 - 1 }

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > max_int() - b { return Err("overflow"); }
  if b < 0 && a < min_int() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 && a > max_int() + b { return Err("overflow"); }
  if b > 0 && a < min_int() + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a > 0 {
    if b > 0 {
      if a > max_int() / b { return Err("overflow"); }
    } else {
      if b < min_int() / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if a < min_int() / b { return Err("overflow"); }
    } else {
      if a < max_int() / b { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn neg(a: Int) -> Result<Int, Str> {
  if a == min_int() { return Err("overflow"); }
  Ok(-a)
}

fn power(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if a == 0 { return Ok(if b == 0 { 1 } else { 0 }); }
  if a == 1 { return Ok(1); }
  if a == -1 { return Ok(if b % 2 == 0 { 1 } else { -1 }); }
  if b >= 64 { return Err("overflow"); }
  let mut r = 1;
  for _i in 0..b {
    r = mul(r, a)?;
  }
  Ok(r)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if op == "+" { return add(a, b); }
  if op == "-" { return sub(a, b); }
  if op == "*" { return mul(a, b); }
  if op == "/" {
    if b == 0 { return Err("division by zero"); }
    if a == min_int() && b == -1 { return Err("overflow"); }
    return Ok(a / b);
  }
  if op == "%" {
    if b == 0 { return Err("division by zero"); }
    if b == -1 { return Ok(0); }
    return Ok(a % b);
  }
  power(a, b)
}

fn ev(n: Node, env: Map<Str, Int>) -> Result<Int, Str> {
  if n.kind == 0 {
    return match n.text.parse_int() {
      Some(v) => Ok(v),
      None => Err("overflow"),
    };
  }
  if n.kind == 1 {
    return match env.get(n.text) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n.text),
    };
  }
  if n.kind == 4 {
    let a = ev(n.kids[0], env)?;
    return neg(a);
  }
  if n.kind == 3 {
    let a = ev(n.kids[0], env)?;
    let b = ev(n.kids[1], env)?;
    return binop(n.text, a, b);
  }
  let name = n.text;
  let argc = n.kids.len();
  let want = if name == "min" || name == "max" { 2 } else if name == "abs" { 1 } else { -1 };
  if want < 0 { return Err("unknown function " + name); }
  if argc != want { return Err("wrong number of arguments to " + name); }
  let a = ev(n.kids[0], env)?;
  if want == 1 {
    if a < 0 { return neg(a); }
    return Ok(a);
  }
  let b = ev(n.kids[1], env)?;
  if name == "min" { return Ok(a.min(b)); }
  Ok(a.max(b))
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let lines = text.lines();
  let mut env: Map<Str, Int> = Map::new();
  let mut out = "";
  for idx in 0..lines.len() {
    let line = lines[idx];
    if line.trim() == "" { continue; }
    let num = (idx + 1).to_str();
    let parsed = match tokenize(line) {
      Some(t) => parse_line(t),
      None => None,
    };
    let Some(st) = parsed else {
      out = out + num + ": error: syntax error\n";
      continue;
    };
    match ev(st.expr, env) {
      Ok(v) => {
        if st.is_let {
          env.insert(st.name, v);
          out = out + num + ": " + st.name + " = " + v.to_str() + "\n";
        } else {
          out = out + num + ": " + v.to_str() + "\n";
        }
      }
      Err(e) => {
        out = out + num + ": error: " + e + "\n";
      }
    }
  }
  Ok(out)
}

struct Ev { id: Str, ty: Str, sub: Str, seq: Int }

fn text(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn int(v: SqlValue) -> Int {
  match v { SqlValue::Int(n) => n, _ => 0 }
}

fn send(res: Outgoing, status: Int, body: Str) -> Result<(), Str> {
  res.send(status, ["content-type"], ["application/json"], body.to_bytes()).map_err(|e| "send failed")
}

fn status_body(s: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str(s));
  Json::Obj(m).to_json()
}

fn header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() {
    if names[i] == name { return Some(values[i]); }
  }
  None
}

fn sig_ok(req: Incoming, secrets: Dir) -> Result<Bool, Str> {
  let key = secrets.read("webhook.key").map_err(|e| "no key")?;
  let mut k = key;
  if k.len() > 0 {
    if k[k.len() - 1] == 10 { k = k.slice(0, k.len() - 1); }
  }
  let mut m = k;
  m.extend(".".to_bytes());
  m.extend(req.body());
  let expected = "sha256=" + m.sha256().to_hex();
  match header(req, "x-signature") {
    Some(s) => Ok(expected.ct_eq(s)),
    None => Ok(false),
  }
}

fn parse_event(body: Bytes) -> Option<Ev> {
  let j = body.to_str().parse_json().ok()?;
  j.as_map()?;
  let id = j.get("id").and_then(|x| x.as_str())?;
  let ty = j.get("type").and_then(|x| x.as_str())?;
  let sub = j.get("subscription").and_then(|x| x.as_str())?;
  let seq = j.get("seq").and_then(|x| x.as_int())?;
  if seq < 1 { return None; }
  if ty == "subscription.created" || ty == "subscription.activated" || ty == "payment.failed" || ty == "subscription.canceled" {
    Some(Ev { id: id, ty: ty, sub: sub, seq: seq })
  } else {
    None
  }
}

fn next_state(state: Str, ty: Str) -> Str {
  if ty == "subscription.created" {
    if state == "none" { return "created"; }
  } else if ty == "subscription.activated" {
    if state == "created" || state == "past_due" { return "active"; }
  } else if ty == "payment.failed" {
    if state == "active" { return "past_due"; }
  } else if ty == "subscription.canceled" {
    if state == "created" || state == "active" || state == "past_due" { return "canceled"; }
  }
  ""
}

fn schema(db: Db) -> Result<(), Str> {
  db.exec("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, subscription TEXT NOT NULL, seq INTEGER NOT NULL, type TEXT NOT NULL, applied INTEGER NOT NULL)", []).map_err(|e| "db")?;
  db.exec("CREATE INDEX IF NOT EXISTS events_sub_seq ON events(subscription, seq)", []).map_err(|e| "db")?;
  db.exec("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL)", []).map_err(|e| "db")?;
  db.exec("CREATE TABLE IF NOT EXISTS hist (sub TEXT NOT NULL, n INTEGER NOT NULL, state TEXT NOT NULL, PRIMARY KEY (sub, n))", []).map_err(|e| "db")?;
  Ok(())
}

fn insert_event(db: Db, ev: Ev, applied: Int) -> Result<Int, DbErr> {
  db.exec("INSERT INTO events(id, subscription, seq, type, applied) VALUES (?, ?, ?, ?, ?)",
    [SqlValue::Text(ev.id), SqlValue::Text(ev.sub), SqlValue::Int(ev.seq), SqlValue::Text(ev.ty), SqlValue::Int(applied)])
}

fn handle_webhook(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<(), Str> {
  if !sig_ok(req, secrets)? {
    let w = log.write("rejected signature");
    return send(res, 401, "{\"error\":\"bad signature\"}");
  }
  let Some(ev) = parse_event(req.body()) else {
    return send(res, 400, "{\"error\":\"invalid event\"}");
  };
  let dup = db.query("SELECT 1 FROM events WHERE id = ?", [SqlValue::Text(ev.id)]).map_err(|e| "db")?;
  if dup.len() > 0 {
    return send(res, 200, status_body("duplicate"));
  }
  let srows = db.query("SELECT state, seq FROM subs WHERE id = ?", [SqlValue::Text(ev.sub)]).map_err(|e| "db")?;
  let mut cur_state = "none";
  let mut last = 0;
  if srows.len() > 0 {
    cur_state = text(srows[0][0]);
    last = int(srows[0][1]);
  }
  if ev.seq <= last {
    return match insert_event(db, ev, 1) {
      Ok(n) => send(res, 200, status_body("stale")),
      Err(DbErr::Constraint(m)) => send(res, 200, status_body("duplicate")),
      Err(e) => Err("db"),
    };
  }
  if ev.seq > last + 1 {
    return match insert_event(db, ev, 0) {
      Ok(n) => send(res, 202, status_body("queued")),
      Err(DbErr::Constraint(m)) => send(res, 200, status_body("duplicate")),
      Err(e) => Err("db"),
    };
  }
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  stmts.push("INSERT INTO events(id, subscription, seq, type, applied) VALUES (?, ?, ?, ?, 1)");
  params.push([SqlValue::Text(ev.id), SqlValue::Text(ev.sub), SqlValue::Int(ev.seq), SqlValue::Text(ev.ty)]);
  let mut state = cur_state;
  let mut n = ev.seq;
  let mut count = 0;
  let mut ty = ev.ty;
  let mut eid = ev.id;
  loop {
    count += 1;
    let ns = next_state(state, ty);
    if ns == "" {
      let w = log.write("invalid transition " + eid);
    } else {
      state = ns;
      stmts.push("INSERT INTO hist(sub, n, state) VALUES (?, ?, ?)");
      params.push([SqlValue::Text(ev.sub), SqlValue::Int(n), SqlValue::Text(ns)]);
    }
    let rows = db.query("SELECT id, type FROM events WHERE subscription = ? AND seq = ? AND applied = 0 ORDER BY rowid LIMIT 1",
      [SqlValue::Text(ev.sub), SqlValue::Int(n + 1)]).map_err(|e| "db")?;
    if rows.len() == 0 { break; }
    n += 1;
    eid = text(rows[0][0]);
    ty = text(rows[0][1]);
    stmts.push("UPDATE events SET applied = 1 WHERE id = ?");
    params.push([SqlValue::Text(eid)]);
  }
  stmts.push("INSERT INTO subs(id, state, seq) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq");
  params.push([SqlValue::Text(ev.sub), SqlValue::Text(state), SqlValue::Int(n)]);
  stmts.push("UPDATE events SET applied = 1 WHERE subscription = ? AND seq <= ? AND applied = 0");
  params.push([SqlValue::Text(ev.sub), SqlValue::Int(n)]);
  match db.transaction(stmts, params) {
    Ok(x) => {
      let mut m: Map<Str, Json> = Map::new();
      m.insert("status", Json::Str("applied"));
      m.insert("applied", Json::Num(count));
      send(res, 200, Json::Obj(m).to_json())
    },
    Err(DbErr::Constraint(m)) => send(res, 200, status_body("duplicate")),
    Err(e) => Err("db"),
  }
}

fn handle_get(res: Outgoing, db: Db, id: Str) -> Result<(), Str> {
  let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [SqlValue::Text(id)]).map_err(|e| "db")?;
  if rows.len() == 0 {
    return send(res, 404, "{\"error\":\"not found\"}");
  }
  let hrows = db.query("SELECT state FROM hist WHERE sub = ? ORDER BY n", [SqlValue::Text(id)]).map_err(|e| "db")?;
  let mut hist: List<Json> = [];
  for r in hrows { hist.push(Json::Str(text(r[0]))); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str(id));
  m.insert("state", Json::Str(text(rows[0][0])));
  m.insert("seq", Json::Num(int(rows[0][1])));
  m.insert("history", Json::Arr(hist));
  send(res, 200, Json::Obj(m).to_json())
}

fn handle(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<(), Str> {
  schema(db)?;
  let target = req.target();
  let path = target.split("?")[0];
  let method = req.method();
  if method == "POST" && path == "/webhooks" {
    return handle_webhook(req, res, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      if id.len() > 0 {
        return handle_get(res, db, id);
      }
    }
  }
  send(res, 404, "{\"error\":\"not found\"}")
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Str> {
  handle(req, res, db, secrets, log)?;
  Ok("done")
}
